// ===== "WHO IS THIS?" BIOS — short summaries shown by the "Who is this?" button =====
// Key = the artist text EXACTLY as written in concerts.js. text = 2-3 plain sentences. source = where the facts came from.
// No entry = no button. See EDITING.md.
const W = 'https://en.wikipedia.org/wiki/';
const BIOS = {
  "Austin Snell – Colors Tour 2026": { text: "Austin Snell is a country singer-songwriter from Georgia and a U.S. Air Force veteran who calls his sound \"grunge country\" — country storytelling with hard-rock guitars. He broke out on social media with \"Excuse the Mess\" and is known for \"Pray All the Way Home\"; his debut album Still Bleeding came out in 2024.", source: "https://www.austinsnell.com/" },
  "Emma Willmann (Oct 22–24)": { text: "Emma Willmann is a stand-up comedian and actress who made her TV stand-up debut on The Late Show with Stephen Colbert. She also had a recurring role as Beth on The CW's Crazy Ex-Girlfriend.", source: W + "Emma_Willmann" },
  "Judah & The Lion": { text: "Judah & the Lion are a band from Nashville, Tennessee, formed in 2011. They've released five studio albums; the band is currently Judah Akers and Brian Macdonald.", source: W + "Judah_%26_the_Lion" },
  "Jessica Audiffred": { text: "Jessica Audiffred is a DJ and bass-music producer from Mexico City, mixing dubstep and bass house. She has played festivals like EDC, Ultra, Lollapalooza and Tomorrowland, founded the label A Records, and released her debut album Rave New World in 2025.", source: "https://www.jessica-audiffred.com/" },
  "Sleeping With Sirens – An Ending In Itself Tour": { text: "Sleeping with Sirens is a rock band formed in Orlando, Florida, in 2009 and fronted by singer Kellin Quinn. Signed to Rise Records, they've released eight studio albums and are a mainstay of the post-hardcore/emo scene.", source: W + "Sleeping_with_Sirens" },
  "Amaze & Amuse: A Modern Day Magic Show (18+) with Trino and Parker William": { text: "An adults-only comedy magic show with lots of audience participation, being filmed at this performance. Trino is a Grand Rapids comedy magician who has appeared on four seasons of The CW's Masters of Illusion; Parker William is a Minneapolis comedy magician and mentalist.", source: "https://grcmc.org/event/amaze-amuse-a-modern-day-magic-show-18-with-trino-and-parker-william/1696" },
  "LAKEVIEW – Wreck My Night Tour": { text: "Lakeview is a country rock duo — Jesse Denaro and Luke Healy — originally from the Pittsburgh suburbs and now based in Nashville. They formed in 2019 and released their self-titled debut album in 2024.", source: W + "Lakeview_(band)" },
  "All Them Witches (with Emma Ruth Rundle)": { text: "All Them Witches is a rock band from Nashville, Tennessee. Opener Emma Ruth Rundle is a singer-songwriter and guitarist based in Portland, Oregon, with five solo albums and a spot in the band Red Sparowes.", source: W + "All_Them_Witches" },
  "The Story So Far": { text: "The Story So Far is a pop-punk band from Walnut Creek, California, formed in 2007. They're signed to Pure Noise Records and have released five studio albums.", source: W + "The_Story_So_Far_(band)" },
  "Outlander In Concert": { text: "A live concert built around the hit Starz TV series Outlander, the time-travel drama about Claire and Jamie. An orchestra plays Bear McCreary's Emmy-winning score live while key moments from the show play on a big screen; it's officially licensed and made with the series' showrunner.", source: "https://www.devosperformancehall.com/events/2026/outlander-in-concert" },
  "Evan Honer – It's An Even Longer Road Tour": { text: "Evan Honer is an American folk singer-songwriter (and a former diver for the California Baptist Lancers).", source: W + "Evan_Honer" },
  "The Longest Johns – The Ends Of The Earth Tour": { text: "The Longest Johns are a folk group from Bristol, England, who sing sea shanties and traditional English folk songs as well as their own music. They went viral on TikTok in early 2021 with their version of \"Wellerman.\"", source: W + "The_Longest_Johns" },
  "Ringling Bros. and Barnum & Bailey: The Greatest Show On Earth": { text: "Ringling is America's famous traveling circus, billed as \"The Greatest Show on Earth,\" with roots going back to 1871. It took a break from 2017 to 2023 and is now touring again — a big family show at the arena.", source: W + "Ringling_Bros._and_Barnum_%26_Bailey_Circus" },
  "Blue October – The Foiled 20th Anniversary World Tour": { text: "Blue October is a rock band from Houston, Texas, led by singer Justin Furstenfeld. This tour celebrates 20 years of their 2006 album Foiled, which went platinum and includes the hits \"Hate Me\" and \"Into the Ocean.\"", source: W + "Foiled" },
  "American Aquarium": { text: "American Aquarium is an alternative country / Americana band from Raleigh, North Carolina.", source: W + "American_Aquarium" },
  "Chamber Music Society of Lincoln Center: Dvořák, Debussy, and Chaminade": { text: "The Chamber Music Society of Lincoln Center, based at New York's Alice Tully Hall, is the largest chamber music organization in the U.S. This program features piano trios by Dvořák, Debussy and Cécile Chaminade, a French composer so popular in her day that \"Chaminade Clubs\" sprang up across the U.S.", source: "https://www.scmcgr.org/concerts/the-chamber-music-society-of-lincoln-center-dvorak-debussy-and-chaminade-2026" },
  "Chris Webby – Webby's Arcade Tour": { text: "Chris Webby is a rapper known for mixtapes like Bars On Me (2012) and collaborations with DMX, Busta Rhymes and Tory Lanez. His EP There Goes the Neighborhood (2011) reached the edge of the Billboard 200, and his debut album Chemically Imbalanced came out in 2014.", source: W + "Chris_Webby" },
  "GR Symphony: The Nightmare Before Christmas in Concert": { text: "The Grand Rapids Symphony plays Danny Elfman's score live while Tim Burton's The Nightmare Before Christmas (1993) is shown in HD on the big screen. It's the stop-motion musical about Jack Skellington, the King of Halloween Town, who discovers Christmas.", source: "https://www.devosperformancehall.com/events/2026/gr-symphony-presents-disney-tim-burtons-the-nightmare-before-christmas-in-concert-live-to-film" },
  "Noche de Banda: Banda Recoditos & Banda Machos": { text: "A night of regional Mexican banda music. Banda Los Recoditos was formed in Mazatlán, Sinaloa, in 1989 and had a No. 1 Billboard Hot Latin Songs hit with \"Ando Bien Pedo\"; Banda Machos hails from Villa Corona, Jalisco.", source: W + "Banda_Los_Recoditos" },
  "The String Cheese Incident – Just Keep Spinning Tour": { text: "The String Cheese Incident is a jam band from Colorado (Crested Butte and Telluride), formed in 1993.", source: W + "The_String_Cheese_Incident" },
  "Béla Fleck – My Bluegrass Heart": { text: "Béla Fleck is a virtuoso banjo player who blends bluegrass with jazz and other styles. He's known for New Grass Revival and Béla Fleck and the Flecktones, and has won 18 Grammy Awards.", source: W + "B%C3%A9la_Fleck" },
  "Hotel California – The Original Eagles Tribute": { text: "A Canadian tribute band that has been recreating the music of the Eagles since 1986, focusing on matching the band's vocals and harmonies. Expect the Eagles' greatest hits played live.", source: "https://hotelcalifornia.ca/" },
  "Raanan Hershberg (Nov 5–7)": { text: "Raanan Hershberg is a stand-up comedian who has performed on The Tonight Show with Jimmy Fallon, The Late Late Show with James Corden and Comedy Central. His special \"Jokes from the Underground\" made The New York Times' Best Comedy of 2022 list, and he's a regular at New York's Comedy Cellar.", source: "https://www.thebob.com/drgrins/comedian/index.html?id=1289" },
  "GR Symphony: Midori Plays Shostakovich": { text: "Famed violinist Midori — a child prodigy who debuted with the New York Philharmonic at age 11 and became one of the world's leading violinists — joins the Grand Rapids Symphony for Shostakovich's Violin Concerto No. 1. The program also includes music by Ravel.", source: "https://www.grsymphony.org/midori-plays" },
  "Pop Scholars: Improv Comedy": { text: "Pop Scholars is an improv comedy troupe performing fast-paced, made-up-on-the-spot scenes that invite the audience in on the show.", source: "https://www.popscholars.com/" },
  "Trivium – Crown in the Grave World Tour": { text: "Trivium is a heavy metal band from Orlando, Florida, formed in 1999. It's led by singer-guitarist Matt Heafy, with guitarist Corey Beaulieu and bassist Paolo Gregoletto.", source: W + "Trivium_(band)" },
  "Scott Bradlee's Postmodern Jukebox": { text: "Postmodern Jukebox is a rotating musical collective started by pianist Scott Bradlee in 2011 that reworks modern pop hits into vintage styles like swing and jazz. They became famous on YouTube, with billions of views.", source: W + "Postmodern_Jukebox" },
  "Broadway Grand Rapids: Maybe Happy Ending": { text: "Maybe Happy Ending is a musical by Will Aronson and Hue Park about two human-like helper robots, Oliver and Claire, who meet in a future Seoul and form an unexpected bond. It's a story about love and mortality, performed without an intermission.", source: W + "Maybe_Happy_Ending" },
  "Kevin Bozeman (Nov 12–14)": { text: "Kevin Bozeman is a stand-up comedian with a smooth, clever style who got his start at an open mic in Madison, Wisconsin. He performed on Comedy Central's Premium Blend and was a semi-finalist on NBC's Last Comic Standing in 2010.", source: "https://www.thebob.com/drgrins/comedian/index.html?id=578" },
  "GR Symphony: Coffee with Bob (Grace Kim, violin)": { text: "A morning concert with Grand Rapids Symphony Pops conductor Bob Bernhardt, featuring the Symphony's own violinist Grace Kim as soloist. Coffee and doughnuts are available before the concert.", source: "https://www.scmcgr.org/concerts/grand-rapids-symphony" },
  "GR Symphony: From Dvořák to Brahms (Grace Kim, violin)": { text: "A one-night-only Grand Rapids Symphony concert led by Pops conductor Bob Bernhardt, featuring the Symphony's own violinist Grace Kim.", source: "https://www.scmcgr.org/concerts/grand-rapids-symphony-2" },
  "Gabriel Iglesias – The 1976 Tour": { text: "Gabriel \"Fluffy\" Iglesias is a stand-up comedian (one of the 10 highest-paid comedians in 2018) known for specials like I'm Not Fat... I'm Fluffy and Hot and Fluffy. He also starred in Netflix's Mr. Iglesias and appeared in Magic Mike.", source: W + "Gabriel_Iglesias" },
  "Gavin Adcock – The Day I Hang It Up Tour (with Braxton Keith & The Creekers)": { text: "Gavin Adcock is an American country music singer-songwriter. Braxton Keith and The Creekers are also on the bill.", source: W + "Gavin_Adcock" },
  "Classical Recital with Aziza Poggi": { text: "Aziza Poggi is a classically trained mezzo-soprano and Berklee graduate who sings opera, art song, Broadway and symphonic rock. This recital features art songs, opera arias and Broadway favorites with a group of guest singers and pianist Todd Wilkie.", source: "https://www.scmcgr.org/concerts/classical-recital-with-aziza-poggi" },
  "Pentatonix – Christmas in the City Tour": { text: "Pentatonix is an a cappella group from Arlington, Texas, that won NBC's The Sing-Off in 2011 and became a YouTube sensation. They're known for pop covers and Christmas songs built entirely from voices and beatboxing.", source: W + "Pentatonix" },
  "Jason Bonham's Led Zeppelin Evening": { text: "Jason Bonham is an English drummer and the son of Led Zeppelin drummer John Bonham. He has played with the surviving members of Led Zeppelin, including their 2007 reunion concert in London, and this show celebrates Led Zeppelin's music.", source: W + "Jason_Bonham" },
  "Triumph – The Rock & Roll Machine Reloaded": { text: "Triumph is a Canadian rock band formed in 1975, popular in the late '70s and '80s and famous for their live shows. They've earned many gold and platinum awards and are in the Canadian Music Hall of Fame.", source: W + "Triumph_(band)" },
  "GR Symphony: Messiah by Candlelight": { text: "The Grand Rapids Symphony and Symphony Chorus perform Handel's Messiah, the 1741 oratorio that's one of the best-known choral works ever written. It builds to the famous \"Hallelujah\" Chorus.", source: "https://www.grsymphony.org/messiah-candle" },
  "Andrea González Caballero – Spanish Guitar Concert": { text: "Andrea González Caballero is an award-winning Spanish classical guitarist, called \"one of today's young rising stars of the classical guitar\" by BBC Music Magazine. She has won top prizes at the F. Sor and Alhambra competitions and toured internationally with her album Reencuentros.", source: "https://www.scmcgr.org/concerts/andrea-gonzalez-caballero-spanish-guitar-concert" },
  "Annie (Civic Theatre production, Nov 20–Dec 20)": { text: "Annie is the classic Broadway musical about the optimistic orphan from the Little Orphan Annie comic strip, featuring the songs \"Tomorrow\" and \"It's the Hard Knock Life.\" This is a production by Grand Rapids Civic Theatre, one of the largest community theatres in the U.S.", source: W + "Annie_(musical)" },
  "Jamie Lissow (Nov 20–21)": { text: "Jamie Lissow is a comedian and actor who is a regular guest on Fox's Gutfeld! and starred in (and co-wrote) the Netflix series Real Rob. He's appeared on The Tonight Show and Last Comic Standing and has a Comedy Central half-hour special.", source: "https://www.thebob.com/drgrins/comedian/index.html?id=1502" },
  "Underoath – Define the Great Line 20th Anniversary Tour": { text: "Underoath is a rock band from Tampa, Florida, founded in 1997. This tour marks 20 years of their 2006 album Define the Great Line, a metalcore/emo record.", source: W + "Define_the_Great_Line" },
  "Cirque Dreams Holidaze": { text: "A family holiday show that wraps a Broadway-style story around circus acts — aerialists, jugglers, acrobats and more. Reimagined for 2026, it follows young Clara on Christmas Eve into a magical world called Holidaze, with holiday favorites sung live.", source: "https://www.bochcenter.org/events/detail/cirquedreams" },
  "Dave Dyer (Nov 27–28)": { text: "Dave Dyer is a comedian who has worked with Mike Birbiglia, Jim Breuer and Lewis Black, written for Late Night with Jimmy Fallon, and is a frequent guest on the Bob and Tom Show. He's also a full-time firefighter with the Grand Rapids Township Fire Department.", source: "https://www.thebob.com/drgrins/comedian/index.html?id=1347" },
  "Straight No Chaser – Make Spirits Bright Tour": { text: "Straight No Chaser is an a cappella group that started at Indiana University in 1996. Their comic \"12 Days of Christmas\" video went viral in 2007 and led to a record deal with Atlantic Records.", source: W + "Straight_No_Chaser_(group)" },
  "Love Actually In Concert": { text: "A concert presentation of Love Actually, the 2003 Christmas romantic comedy written and directed by Richard Curtis. The film follows ten interlinked London love stories in the weeks leading up to Christmas.", source: W + "Love_Actually" },
  "Mannheim Steamroller Christmas": { text: "Mannheim Steamroller is a neoclassical new-age group founded by Chip Davis in 1974, best known for its Fresh Aire albums and its modern Christmas music recordings. The group has sold 28 million albums in the U.S.", source: W + "Mannheim_Steamroller" },
  "Christmas Together with Amy Grant & Michael W. Smith": { text: "A holiday concert with two Christian music stars. Amy Grant, called \"The Queen of Christian Pop,\" crossed over to pop in the 1980s; Michael W. Smith has sold more than 18 million albums and hit the Top 10 in 1991 with \"Place in This World.\"", source: W + "Amy_Grant" },
  "Brian Simpson (Dec 3–5)": { text: "Brian Simpson is a stand-up comedian who's a regular at The Comedy Store and The Comedy Mothership and was named one of Variety's Top Comics to Watch. His debut Netflix hour is Brian Simpson: Live from the Mothership.", source: "https://www.thebob.com/drgrins/comedian/index.html?id=1463" },
  "GR Symphony Holiday Pops": { text: "The Grand Rapids Symphony's annual Holiday Pops concerts, presented by Meijer. Founded in 1930, the Symphony gives more than 400 performances across Michigan each year.", source: "https://www.devosperformancehall.com/events/2026/the-gr-symphony-presents-holiday-pops" },
  "WWE Friday Night SmackDown": { text: "SmackDown is one of WWE's two flagship pro wrestling TV shows, airing live on Friday nights since 1999. This is a live event at the arena with SmackDown brand wrestlers.", source: W + "WWE_SmackDown" },
  "Sarah Jarosz – 10 Years of Undercurrent": { text: "Sarah Jarosz is a singer-songwriter and multi-instrumentalist from Wimberley, Texas, playing folk and Americana. This tour marks 10 years of her 2016 album Undercurrent, which won two Grammy Awards.", source: W + "Undercurrent_(Sarah_Jarosz_album)" },
  "Trans-Siberian Orchestra – The Ghosts of Christmas Eve": { text: "Trans-Siberian Orchestra is a rock band founded by Paul O'Neill in 1996, famous for huge holiday arena shows mixing rock and classical music. The Ghosts of Christmas Eve is based on their 1999 TV special.", source: W + "Trans-Siberian_Orchestra" },
  "An Evening with Lord Huron": { text: "Lord Huron is an indie folk/rock band from Los Angeles led by founder Ben Schneider. Their albums include Lonesome Dreams (2012), Strange Trails (2015) and The Cosmic Selector Vol. 1 (2025).", source: W + "Lord_Huron" },
  "Jeff Daniels": { text: "Jeff Daniels is the actor known for both comedy and drama on stage and screen — a two-time Primetime Emmy winner with Tony and Golden Globe nominations. He's also a musician, and these are his music concerts.", source: W + "Jeff_Daniels" },
  "Jessica Michelle Singleton (Dec 10–12)": { text: "Jessica Michelle Singleton is a raw, fast-paced stand-up comedian with two #1 comedy albums. She co-hosts the podcast Slobs and was a writer for the Roast of Whitney Cummings.", source: "https://www.thebob.com/drgrins/comedian/index.html?id=1074" },
  "Aoife O'Donovan & Chris Thile": { text: "Two acoustic music stars together. Aoife O'Donovan is a Grammy-winning singer-songwriter known for Crooked Still and the trio I'm with Her; Chris Thile is the mandolinist of Nickel Creek and Punch Brothers, a MacArthur Fellow and former host of radio's Live from Here.", source: W + "Chris_Thile" },
  "Michael Kosta – Big Dad Energy": { text: "Michael Kosta is a stand-up comedian and former professional tennis player. He's an Emmy-winning correspondent and rotating host on The Daily Show.", source: W + "Michael_Kosta" },
  "for KING + COUNTRY – A Drummer Boy Christmas": { text: "for KING + COUNTRY is a Christian pop duo of brothers Joel and Luke Smallbone, born in Australia and raised in the Nashville area. This is their holiday tour.", source: W + "For_King_%26_Country_(band)" },
  "An Evening with John Cusack": { text: "An evening with actor John Cusack, whose four-decade career spans more than ninety films, from Sixteen Candles and Say Anything... to Grosse Pointe Blank, Serendipity and Hot Tub Time Machine.", source: W + "John_Cusack" },
  "The MeatEater Christmas Tour": { text: "A live holiday show from MeatEater, the hunting and outdoors TV series hosted by Steven Rinella, which has aired on Netflix and the MeatEater YouTube channel.", source: W + "MeatEater" },
  "Jonas Brothers – The Burning Up Tour": { text: "The Jonas Brothers are a pop rock band of brothers Kevin, Joe and Nick Jonas from New Jersey. They rose to fame on Disney Channel (Camp Rock, Jonas) and have released seven albums.", source: W + "Jonas_Brothers" },
  "GR Symphony: The Muppet Christmas Carol in Concert": { text: "The Grand Rapids Symphony performs the score live while The Muppet Christmas Carol (1992) plays on the big screen. Kermit, Miss Piggy and the Muppets tell Charles Dickens' classic story; the film is rated G.", source: "https://www.devosperformancehall.com/events/2026/gr-symphony-presents-the-muppet-christmas-carol-in-concert-live-to-film" },
  "Michael Longfellow (Dec 17–19)": { text: "Michael Longfellow is a comedian and actor who spent three seasons in the cast of Saturday Night Live (2022–2025).", source: W + "Michael_Longfellow" },
  "Rene Vaca & That Mexican OT": { text: "That Mexican OT is a rapper from Bay City, Texas, best known for his 2023 single \"Johnny Dang,\" which made the Billboard Hot 100; his debut album is Lonestar Luchador. He shares the bill with Rene Vaca.", source: W + "That_Mexican_OT" },
  "Dolly Parton's Smoky Mountain Christmas Carol": { text: "A stage musical with music and lyrics by Dolly Parton that retells Dickens' A Christmas Carol, moved to the Great Smoky Mountains of Tennessee in the 1930s.", source: W + "Dolly_Parton's_Smoky_Mountain_Christmas_Carol" },
  "Jason Carter & Michael Cleveland": { text: "Jason Carter is a three-time Grammy winner and founding member of the Travelin' McCourys, with five IBMA Fiddle Player of the Year awards. Michael Cleveland is the most awarded IBMA Fiddle Player of the Year, with twelve wins.", source: "https://www.scmcgr.org/concerts/jason-carter-michael-cleveland-2027" },
  "Tommy Emmanuel, CGP – Living In The Light Tour": { text: "Tommy Emmanuel is an Australian guitarist NPR's World Cafe called \"one of the best acoustic guitarists in the world.\" He began touring with his family's band at age six, and has released a string of acclaimed instrumental albums since going solo in 1979.", source: "https://www.scmcgr.org/concerts/tommy-emmanuel-2027" },
  "TobyMac – Hits Deep Tour 2027 (with Jeremy Camp, Seph Schlueter, Katy Nichole)": { text: "TobyMac's annual Hits Deep Tour brings him together with Jeremy Camp, Seph Schlueter and Katy Nichole. Expect TobyMac favorites like \"I just need U.\" and Jeremy Camp's \"I Still Believe.\"", source: "https://www.vanandelarena.com/events/2027/tobymac" },
  "Disney On Ice presents Find Your Hero (Feb 18–21)": { text: "Disney On Ice presents Find Your Hero, an ice show with Mickey, Minnie, Donald and Goofy plus stories from Frozen, Moana, Encanto, The Little Mermaid, Beauty and the Beast and more.", source: "https://www.vanandelarena.com/events/2027/disney-on-ice" },
  "Monster Jam (Mar 12–14)": { text: "Monster Jam, celebrating its 35th anniversary, brings 12,000-pound monster trucks to Van Andel Arena for 5 shows from March 12–14, with a Pit Party before the Saturday and Sunday noon shows.", source: "https://www.vanandelarena.com/events/2027/monster-jam" },
  "Noah Gundersen – Rites of Spring US Tour (with Runnner, Breakup Shoes)": { text: "Noah Gundersen is an indie folk singer-songwriter from Seattle. Runnner and Breakup Shoes open.", source: "https://en.wikipedia.org/wiki/Noah_Gundersen" },
  "Authority Zero – Apocalyptour 2026 (with The Raging Nathans, Bayley Gottfried, Misplaced Memories)": { text: "Authority Zero is a punk rock band from Mesa, Arizona, formed in 1994. Their sound is rooted in reggae and skate punk with Spanish/Portuguese influences, and they've released eight studio albums.", source: "https://en.wikipedia.org/wiki/Authority_Zero" },
  "Psychostick + Texas Toast Chainsaw Massacre + Plethora + Dirtflesh": { text: "Psychostick is a comedy metal band from Tempe, Arizona, known for the humor in their songs and lyrics — a style they call \"humorcore.\" Their debut album was We Couldn't Think of a Title (2003).", source: "https://en.wikipedia.org/wiki/Psychostick" },
  "Blitzkid – Modern Hel Tour (with EPCYA, RTNR, The Burdens)": { text: "Blitzkid is a horror punk band from Bluefield, West Virginia, led by TB Monstrosity and Argyle Goolsby. Active from 1997 to 2012, they reformed in 2020 and have released five studio albums.", source: "https://en.wikipedia.org/wiki/Blitzkid" },
  "CKY + Tombstunner + Stretched Thin (SOLD OUT)": { text: "CKY (short for Camp Kill Yourself) is a rock band from West Chester, Pennsylvania, formed in 1998. They first got noticed through the CKY video series made by skateboarder Bam Margera and his crew.", source: "https://en.wikipedia.org/wiki/CKY_(band)" },
  "Tune-Yards + Rituals of Mine": { text: "Tune-Yards is the Oakland, California, music project of Merrill Garbus and Nate Brenner, known for loop pedals, ukulele, vocals and lo-fi percussion. Their 2011 album Whokill topped The Village Voice's Pazz & Jop critics' poll, and their sixth album, Better Dreaming, came out in 2025.", source: "https://en.wikipedia.org/wiki/Tune-Yards" },
  "Hot Water Music + Signals Midwest + Rodeo Boys + Singing Lungs": { text: "Hot Water Music is a punk rock band formed in 1994 in Gainesville, Florida, with Chuck Ragan and Chris Wollard sharing lead vocals and guitar. Chris Cresswell has also been in the band since 2017.", source: "https://en.wikipedia.org/wiki/Hot_Water_Music" },
  "Choir! Choir! Choir! – Landslide: An Epic Fleetwood Mac Singalong (early show)": { text: "Choir! Choir! Choir! is a choir from Toronto that anyone can join: the audience is the choir. This show is a big group singalong of Fleetwood Mac songs.", source: "https://en.wikipedia.org/wiki/Choir!_Choir!_Choir!" },
  "Choir! Choir! Choir! – Landslide: An Epic Fleetwood Mac Singalong (late show)": { text: "Choir! Choir! Choir! is a choir from Toronto that anyone can join: the audience is the choir. This show is a big group singalong of Fleetwood Mac songs.", source: "https://en.wikipedia.org/wiki/Choir!_Choir!_Choir!" },
  "Kottonmouth Kings": { text: "Kottonmouth Kings are a hip-hop and rap rock group formed in Placentia, California, in 1996 by D-Loc and Saint Dog. Their music sometimes mixes in punk rock, psychedelic rock, reggae and more.", source: "https://en.wikipedia.org/wiki/Kottonmouth_Kings" },
  "Dustin Nickerson": { text: "Dustin Nickerson is a clean stand-up comedian from the Seattle area whose comedy focuses a lot on family life. He tours as a headliner and has often opened for Taylor Tomlinson and Nate Bargatze.", source: "https://en.wikipedia.org/wiki/Dustin_Nickerson" },
  "Nicole Atkins – Drama 2026 Tour (with John Gallagher Jr., The Temperances)": { text: "Nicole Atkins is a singer-songwriter whose influences include 1950s crooners, 1960s psychedelia, soul and Brill Building songwriting. She's often compared to Roy Orbison.", source: "https://en.wikipedia.org/wiki/Nicole_Atkins" },
  "WHY?": { text: "WHY? is an alternative hip-hop and indie rock band founded in 2004 by Cincinnati rapper and singer Yoni Wolf. They've released eight studio albums, including Elephant Eyelash (2005) and Alopecia (2008).", source: "https://en.wikipedia.org/wiki/Why%3F_(American_band)" },
  "Koffin Kats + Voodoo Glow Skulls + Reckless Rhythms": { text: "Voodoo Glow Skulls, on this bill with Koffin Kats, is a ska punk band formed in 1988 in Riverside, California, by brothers Frank, Eddie and Jorge Casillas and their friend Jerry O'Neill.", source: "https://en.wikipedia.org/wiki/Voodoo_Glow_Skulls" },
  "Radiator Hospital": { text: "Radiator Hospital is an indie rock band now based in Philadelphia; songwriter Sam Cook-Parrott is from Grand Rapids. They've released four LPs on Salinas Records.", source: "https://en.wikipedia.org/wiki/Radiator_Hospital" },
  "Honey Revenge + Hunny + Broadside": { text: "Honey Revenge is a pop rock/pop-punk band formed in Los Angeles in 2021 by singer Devin Papadol and guitarist Donny Lloyd. Their debut album, Retrovision, came out in 2023.", source: "https://en.wikipedia.org/wiki/Honey_Revenge" },
  "Jon Spencer": { text: "Jon Spencer is a singer and guitarist from the noise- and garage-rock scenes, known for Pussy Galore, Boss Hog and especially the Jon Spencer Blues Explosion. Since the Blues Explosion ended in 2022 he has kept touring with new bands.", source: "https://en.wikipedia.org/wiki/Jon_Spencer" },
  "feeble little horse – Bitknot Tour (with Snuggle) (SOLD OUT)": { text: "feeble little horse is an indie rock band from Pittsburgh, formed in 2021. They're signed to Saddle Creek Records and have three albums and one EP.", source: "https://en.wikipedia.org/wiki/Feeble_Little_Horse" },
  "Vlad Holiday + Wilson Ave": { text: "Vlad Holiday is a Romanian American singer, songwriter and producer who blends lo-fi, bedroom pop, psych rock and dream pop. He has also written and produced for other artists, including Cage the Elephant's \"Neon Pill,\" a Grammy nominee.", source: "https://en.wikipedia.org/wiki/Vlad_Holiday" },
  "Chasing Abbey": { text: "Chasing Abbey is a trio from Tullamore, Ireland, mixing electronic production with traditional Irish music. Their debut album, Cyber Celt, came out in September 2026.", source: "https://en.wikipedia.org/wiki/Chasing_Abbey" },
  "Pigeons Playing Ping Pong (with Dizgo)": { text: "Pigeons Playing Ping Pong is a funk jam band from Baltimore, Maryland. They built their following by touring constantly, playing as many as 200 shows a year.", source: "https://en.wikipedia.org/wiki/Pigeons_Playing_Ping_Pong" },
  "Said The Sky (18+)": { text: "Said the Sky is Trevor Christensen, an electronic dance music producer, DJ and musician.", source: "https://en.wikipedia.org/wiki/Said_the_Sky" },
  "Pouya – The Forever Glades Tour": { text: "Pouya is a rapper seen as a pioneer of the underground SoundCloud rap scene that began in 2012. He's an independent artist with a long-lasting core fanbase, and he helped discover the duo Suicideboys early in their career.", source: "https://en.wikipedia.org/wiki/Pouya" },
  "Blake Whiten (with Slater Nalley)": { text: "Blake Whiten is a country singer and songwriter. His debut album, Something to Say (2026), includes his first Billboard Hot 100 hit, \"Bet on That.\"", source: "https://en.wikipedia.org/wiki/Blake_Whiten" },
  "almost monday – Thank God It's almost monday": { text: "almost monday is an indie pop band based in San Diego, California.", source: "https://en.wikipedia.org/wiki/Almost_Monday" },
  "Bryan Andrews – Taking My Flag Back Tour": { text: "Bryan Andrews is a country singer and activist best known for politically themed songs, many described as protest songs.", source: "https://en.wikipedia.org/wiki/Bryan_Andrews_(singer)" },
  "Redferrin (with Scout Speer)": { text: "Redferrin (Blake Redferrin) is a country singer-songwriter.", source: "https://en.wikipedia.org/wiki/Redferrin" },
  "Token – I'm Leaving Soon Tour": { text: "Token is a rapper, singer and producer from Salem, Massachusetts, who gained a big following after appearing on Sway's Friday's Fire Cipher. His third album, I'm Leaving Soon, came out in 2026.", source: "https://en.wikipedia.org/wiki/Token_(rapper)" },
  "Tropidelic (with Surfer Girl & The Quasi Kings, Highdeas)": { text: "Tropidelic is a band from Cleveland, Ohio, blending reggae rock, hip-hop and high-energy funk.", source: "https://en.wikipedia.org/wiki/Tropidelic" },
  "Hawthorne Heights – 20th Anniversary of If Only You Were Lonely (with letlive., Creeper)": { text: "Hawthorne Heights is a rock band formed in Dayton, Ohio, in 2001. Their 2006 album If Only You Were Lonely went gold and reached No. 3 on the Billboard 200; this tour marks its 20th anniversary.", source: "https://en.wikipedia.org/wiki/Hawthorne_Heights" },
  "Catch Your Breath – Not Broken Enough Tour": { text: "Catch Your Breath is a rock band from Austin, Texas, founded in 2017. Their single \"Dial Tone\" reached No. 7 on Billboard's Hot Hard Rock chart, and their debut album Shame on Me came out in 2023.", source: "https://en.wikipedia.org/wiki/Catch_Your_Breath_(band)" },
  "Don Broco (with Windwaker)": { text: "Don Broco is an English rock band formed in Bedford in 2008. Their album Amazing Things (2021) topped the UK Albums Chart, and their fifth album, Nightmare Tripping, came out in 2026.", source: "https://en.wikipedia.org/wiki/Don_Broco" },
  "The Free Beer & Hot Wings Live Show (18+)": { text: "The Free Beer and Hot Wings Show is a syndicated morning radio show broadcast mainly from WGRD-FM right here in Grand Rapids, hosted by Gregg \"Free Beer\" Daniels and Chris \"Hot Wings\" Michels. This is a live show at The Intersection starting at 5:30 AM.", source: "https://en.wikipedia.org/wiki/The_Free_Beer_and_Hot_Wings_Show" },
  "Dexter and The Moonrocks – The 12 Steps Tour (SOLD OUT)": { text: "Dexter and the Moonrocks are a rock band from Throckmorton, Texas, formed in 2021, mixing country and rock into what they call \"Western space grunge.\" Their song \"Freakin' Out\" reached No. 33 on the Billboard Hot 100.", source: "https://en.wikipedia.org/wiki/Dexter_and_the_Moonrocks" },
  "Harlem Globetrotters – Rivalry Tour": { text: "The Harlem Globetrotters are an exhibition basketball team that mixes athleticism, theater and comedy. They've played more than 26,000 games in 124 countries, and their signature song is the whistled \"Sweet Georgia Brown.\"", source: "https://en.wikipedia.org/wiki/Harlem_Globetrotters" },
  "PBR: Pendleton Whisky Velocity Tour (Jan 22–23)": { text: "PBR (Professional Bull Riders) is the world's largest bull riding league, based in Fort Worth, Texas. Its Velocity Tour comes to Van Andel Arena for two nights.", source: "https://en.wikipedia.org/wiki/Professional_Bull_Riders" },
  "Grace and Mamrie Present “This Might Get Weird”": { text: "Comedians and internet personalities Grace Helbig and Mamrie Hart co-host the podcast This Might Get Weird (2018–present). Helbig created the web series DailyGrace, and Hart is known for her YouTube show You Deserve a Drink.", source: "https://en.wikipedia.org/wiki/Grace_Helbig" },
  "Dear Evan Hansen (Civic Theatre production, Feb 19–Mar 7)": { text: "Dear Evan Hansen is the musical by Benj Pasek, Justin Paul and Steven Levenson about a high school senior with social anxiety. It won six Tony Awards, including Best Musical; this is a Grand Rapids Civic Theatre production.", source: "https://en.wikipedia.org/wiki/Dear_Evan_Hansen" },
  "Our Town (Civic Theatre production, Apr 23–May 2)": { text: "Our Town is Thornton Wilder's 1938 three-act play about everyday life in the fictional town of Grover's Corners, narrated by a stage manager and performed on a mostly bare stage. It won the Pulitzer Prize for Drama; this is a Grand Rapids Civic Theatre production.", source: "https://en.wikipedia.org/wiki/Our_Town" },
  "Now Clap! Bob The Drag Queen's on Tour": { text: "Bob the Drag Queen is an American drag queen, comedian, actor and podcaster, best known for winning season eight of RuPaul's Drag Race. He later co-hosted HBO's We're Here and appeared in shows such as High Maintenance and A Black Lady Sketch Show.", source: W + "Bob_the_Drag_Queen" },
  "49 Winchester – Change of Plans Tour": { text: "49 Winchester is a country rock band formed in 2013 in Castlewood, Virginia. They've released five studio albums, are signed to New West Records, and have opened for acts like Luke Combs, Tyler Childers and Whiskey Myers.", source: W + "49_Winchester" },
  "Domestic Problems (with Knee Deep Shag)": { text: "Domestic Problems is a band from Grand Rapids, Michigan, and a regular at The Intersection. Knee Deep Shag is the support act.", source: "https://www.concertarchives.org/bands/domestic-problems-d1816fda-ede9-4476-a6de-2d6cc73f0b70" },
  "Music For The Masses: Depeche Mode vs. Nine Inch Nails": { text: "Music For The Masses is a Depeche Mode tribute act. This show covers the classic songs of both Depeche Mode and Nine Inch Nails.", source: "https://www.eventbrite.com/e/music-for-the-masses-depeche-mode-vs-nine-inch-nails-tickets-2002734409531" },
  "L7: The Last Hurrah Tour (with VIAL)": { text: "L7 is an American punk rock band founded in Los Angeles in 1985, re-formed in 2014 after splitting in 2001. Their song \"Pretend We're Dead\" hit the top 10 of Billboard's Modern Rock chart in 1992; this is billed as their \"Last Hurrah Tour.\"", source: W + "L7_(band)" },
  "Andrea Gibson's Love Letter from the Afterlife": { text: "Andrea Gibson was an American poet and activist, named Colorado's Poet Laureate in 2023. This event screens a film of Gibson's final live poetry performance (Denver, 2024) with the score played live by the Goosebump Orchestra, hosted by Megan Falley with guests including Chris Pureka.", source: "https://silvasbigroom.com/event/andrea-gibsons-love-letter-from-the-afterlife/" },
  "David Cross": { text: "David Cross is an American stand-up comedian, actor and writer, best known for co-creating HBO's Mr. Show with Bob and David and playing Tobias Fünke on Arrested Development.", source: W + "David_Cross" },
  "Leslie Jones – I'm Hot Tour": { text: "Leslie Jones is an American stand-up comedian and actress who was a cast member and writer on Saturday Night Live from 2014 to 2019, earning two Emmy nominations. She also starred in Ghostbusters (2016) and hosted ABC's Supermarket Sweep.", source: W + "Leslie_Jones_(comedian)" },
  "Lucas Zelnick": { text: "Lucas Zelnick is an American stand-up comedian.", source: W + "Lucas_Zelnick" },
  "Michigander – 3rd Annual Holiday Special, Night One (with Metal Bubble Trio, Dawning)": { text: "Michigander is a rock project from Kalamazoo, Michigan, started in 2014 and led by singer, songwriter and multi-instrumentalist Jason Singer. This is night one of the band's annual holiday show.", source: W + "Michigander_(band)" },
  "Michigander – 3rd Annual Holiday Special, Night Two (with Jack Droppers and the Best Intentions, CeCe Coakley)": { text: "Michigander is a rock project from Kalamazoo, Michigan, started in 2014 and led by singer, songwriter and multi-instrumentalist Jason Singer. This is night two of the band's annual holiday show.", source: W + "Michigander_(band)" },
  "Rehash + The Flooks + Vert Terms": { text: "Rehash is a rock band from Hallandale Beach in South Florida, headlining with support from The Flooks and Vert Terms.", source: W + "Rehash_(band)" },
  "Duff Goldman": { text: "Duff Goldman is an American pastry chef and TV personality, best known for the Charm City Cakes bakery in Baltimore and its Food Network show Ace of Cakes.", source: W + "Duff_Goldman" },
  "Jeff Allen – Christmas Tour 2026": { text: "Jeff Allen is an American comedian known for his film Happy Wife, Happy Life, Revisited and comedy films like Apostles of Comedy.", source: W + "Jeff_Allen_(comedian)" },
  "Jackson Dean – Magnolia Sage Tour": { text: "Jackson Dean is an American country singer-songwriter signed to Big Machine Records, with charting singles including \"Don't Come Lookin'\" and \"Fearless\".", source: W + "Jackson_Dean" },
  "Jon B": { text: "Jon B is an American R&B singer, songwriter and producer whose hits include \"Someone to Love\" and \"They Don't Know.\" His 1997 album Cool Relax went platinum.", source: W + "Jon_B." },
  "Mustard Plug's Annual Ska-liday Show (with Flatfoot 56, Wack Trucks, Dance Contraption)": { text: "Mustard Plug is a ska punk band from Grand Rapids, Michigan. This is their annual holiday hometown show.", source: W + "Mustard_Plug" },
  "Marlon Wayans": { text: "Marlon Wayans is an American actor and comedian known for The Wayans Bros. sitcom and films like Scary Movie and White Chicks.", source: W + "Marlon_Wayans" },
  "Broadway Grand Rapids: SIX": { text: "Six is a British pop musical by Toby Marlow and Lucy Moss. The six wives of Henry VIII retell their stories as a singing competition and pop concert.", source: W + "Six_(musical)" },
  "A Chorus Line (Civic Theatre production, Jan 15–24)": { text: "A Chorus Line is a 1975 musical conceived by Michael Bennett, with music by Marvin Hamlisch, staged here by Grand Rapids Civic Theatre.", source: W + "A_Chorus_Line" },
  "Chris Fleming Live": { text: "Chris Fleming is an American comedian and actor, first known for the YouTube series Gayle. Their special Chris Fleming: Live at the Palace earned a 2026 Emmy nomination.", source: W + "Chris_Fleming_(comedian)" },
  "Jimmy O. Yang – Has No Friends": { text: "Jimmy O. Yang is a stand-up comedian and actor best known as Jian-Yang on HBO's Silicon Valley and for Crazy Rich Asians.", source: W + "Jimmy_O._Yang" },
  "Dylan Scott": { text: "Dylan Scott is an American country singer and songwriter signed to Curb Records.", source: W + "Dylan_Scott" },
  "Shayne Smith – Forgive Me Father Tour": { text: "Shayne Smith is an American stand-up comedian, writer and podcaster, and the singer for the rock band Painted Devils.", source: W + "Shayne_Smith_(comedian)" },
  "The Hip Abduction – Lost Coast Tour (with Moon Taxi, acoustic)": { text: "The Hip Abduction is a reggae band from St. Petersburg, Florida, formed in 2010.", source: W + "The_Hip_Abduction" },
  "As I Lay Dying": { text: "As I Lay Dying is a metalcore band from San Diego, formed in 2000, with eight albums released.", source: W + "As_I_Lay_Dying_(band)" },
  "Broadway Grand Rapids: Beauty and the Beast (Feb 9–14)": { text: "Disney's Beauty and the Beast is the stage musical of the 1991 animated film, with music by Alan Menken and lyrics by Howard Ashman and Tim Rice.", source: W + "Beauty_and_the_Beast_(musical)" },
  "Nickelback – Everything Under The Sun Tour": { text: "Nickelback is a Canadian rock band formed in 1995 in Hanna, Alberta, fronted by singer and guitarist Chad Kroeger.", source: W + "Nickelback" },
  "Badfish – A Tribute to Sublime: Watch Your Mouth 2027 Tour": { text: "Badfish is a Sublime tribute band formed in 2001 at the University of Rhode Island, named after a song on Sublime's 40oz. to Freedom.", source: W + "Badfish_(band)" },
  "Ashley Cooke – The Baby Blues Tour": { text: "Ashley Cooke is a country singer-songwriter from Parkland, Florida, signed to Big Loud.", source: W + "Ashley_Cooke" },
  "Ryan Hamilton – Making Good Time": { text: "Ryan Hamilton is a clean stand-up comedian known for observational, self-deprecating humor. He has appeared on The Tonight Show, The Late Show and Conan.", source: W + "Ryan_Hamilton_(comedian)" },
  "John Scofield & Dave Holland Duo": { text: "Guitarist John Scofield first got wide attention in Miles Davis's band, and his music blends jazz, funk, blues and rock. He plays here as a duo with bassist Dave Holland.", source: W + "John_Scofield" },
  "Shovels & Rope": { text: "Shovels & Rope is a folk duo from Charleston, South Carolina: husband and wife Michael Trent and Cary Ann Hearst. Their sound mixes folk, rock and roll and country rock.", source: W + "Shovels_%26_Rope" },
  "Dropkick Murphys": { text: "Dropkick Murphys are a Celtic punk band formed in 1996 in Quincy, Massachusetts, known for loud, energetic live shows.", source: W + "Dropkick_Murphys" },
  "NEEDTOBREATHE – The Long Surrender Tour": { text: "Needtobreathe is a rock band from Seneca, South Carolina. They first became known for their Christian themes and later crossed over to mainstream success.", source: W + "Needtobreathe" },
  "Broadway Grand Rapids: Death Becomes Her (Mar 2–7)": { text: "Death Becomes Her is a musical based on the 1992 film. It premiered in Chicago in 2024 and opened on Broadway that November.", source: W + "Death_Becomes_Her_(musical)" },
  "GR Symphony: Cirque de la Symphonie – Fire & Ice": { text: "Cirque de la Symphonie is a touring troupe from Athens, Georgia, whose circus acts are timed to music played live by a symphony orchestra, here the Grand Rapids Symphony.", source: W + "Cirque_de_la_Symphonie" },
  "Ali Wong – Live": { text: "Ali Wong is an American comedian and actress whose awards include two Primetime Emmys and three Golden Globes.", source: W + "Ali_Wong" },
  "Cécile McLorin Salvant & Sullivan Fortner": { text: "Cécile McLorin Salvant is a French-American jazz singer and three-time winner of the Best Jazz Vocal Album Grammy. She is joined by Grammy-winning jazz pianist Sullivan Fortner.", source: W + "C%C3%A9cile_McLorin_Salvant" },
  "Gianmarco Soresi – The Misery Loves Tour": { text: "Gianmarco Soresi is an American stand-up comedian, actor and podcaster known for observational comedy.", source: W + "Gianmarco_Soresi" },
  "Justin Willman – One For The Ages": { text: "Justin Willman is a magician and comedian, the creator and star of Netflix's Magic for Humans.", source: W + "Justin_Willman" },
  "Iliza Shlesinger – Free Nights & Weekends": { text: "Iliza Shlesinger is a stand-up comedian and actress who won NBC's Last Comic Standing in 2008. She has six Netflix comedy specials.", source: W + "Iliza_Shlesinger" },
  "Brit Floyd – Animals 50 World Tour": { text: "Brit Floyd is a Pink Floyd tribute band formed in Liverpool, England, in 2011 by Damian Darlington.", source: W + "Brit_Floyd" },
  "Josiah Queen – Damascus Road Tour": { text: "Josiah Queen is a Christian singer-songwriter from Tampa, Florida. His 2024 debut album The Prodigal hit No. 1 on Billboard's Top Christian Albums chart.", source: W + "Josiah_Queen" },
  "Dylan Gossett – The Ramblin' Tour 2027": { text: "Dylan Gossett is a country singer-songwriter from Austin, Texas, whose song \"Coal\" made the Billboard Hot 100. His debut album Westward came out in 2025.", source: W + "Dylan_Gossett" },
  "Staind – Break The Cycle 25th Anniversary": { text: "Staind is a rock band from Springfield, Massachusetts, formed in 1995 and fronted by Aaron Lewis. This tour marks 25 years of their 2001 album Break the Cycle.", source: W + "Staind" },
  "Branford Marsalis & Dianne Reeves Celebrate John Coltrane": { text: "Saxophonist Branford Marsalis leads the Branford Marsalis Quartet and led The Tonight Show Band from 1992 to 1995. He's joined by jazz singer Dianne Reeves, a five-time Grammy winner.", source: W + "Branford_Marsalis" },
  "Warren Zeiders – No Brakes Tour": { text: "Warren Zeiders is an American country singer-songwriter whose \"Pretty Little Poison\" was his first No. 1 on country radio. No Brakes (2026) is his latest album.", source: W + "Warren_Zeiders" },
  "Foy Vance": { text: "Foy Vance is a singer-songwriter from Northern Ireland, signed to Ed Sheeran's Gingerbread Man label. He has toured as Sheeran's opening act.", source: W + "Foy_Vance" },
  "Jeff Dunham – Inappropriate Contact": { text: "Jeff Dunham is an American ventriloquist and stand-up comedian with many Comedy Central and Netflix specials.", source: W + "Jeff_Dunham" },
  "Chamber Music Society of Lincoln Center – Rhapsody in Blue": { text: "The Chamber Music Society of Lincoln Center is a New York chamber music organization based at Alice Tully Hall, the largest of its kind in the U.S.", source: W + "Chamber_Music_Society_of_Lincoln_Center" },
  "Chamber Music Society of Lincoln Center – String Radiance": { text: "The Chamber Music Society of Lincoln Center is a New York chamber music organization based at Alice Tully Hall, the largest of its kind in the U.S.", source: W + "Chamber_Music_Society_of_Lincoln_Center" },
  "Chamber Music Society of Lincoln Center – Mozart & Brahms Clarinet Quintets": { text: "The Chamber Music Society of Lincoln Center is a New York chamber music organization based at Alice Tully Hall, the largest of its kind in the U.S.", source: W + "Chamber_Music_Society_of_Lincoln_Center" },
  "Menopause The Musical": { text: "Menopause The Musical (2001) follows four women at a lingerie sale, with parodies of baby-boomer-era pop songs about menopause.", source: W + "Menopause_The_Musical" },
  "MercyMe (with Ben Fuller & Peter Burton)": { text: "MercyMe is a contemporary Christian band from Edmond, Oklahoma, fronted by singer Bart Millard.", source: W + "MercyMe" },
  "Opera Grand Rapids: Carmen (Apr 30 & May 1)": { text: "Carmen is Georges Bizet's four-act French opera, first performed in Paris in 1875.", source: W + "Carmen" },
  "Denny Love – Show Love Tour": { text: "Denny Love is an American actor and comedian known for Looking for Alaska and Mayor of Kingstown.", source: W + "Denny_Love" },
  "Candlelight: A Haunted Evening of Halloween Classics (6:30 show)": { text: "A one-hour Candlelight concert of Halloween music played by the KalHaven String Quartet in a candlelit Wealthy Theatre. The program includes Thriller, the Beetlejuice, Addams Family, Halloween and Ghostbusters themes, Danse Macabre and Night on Bald Mountain; ages 8+.", source: "https://grcmc.org/theatre/event/candlelight-concert-a-haunted-evening-of-halloween-classics/1589" },
  "Candlelight: A Haunted Evening of Halloween Classics (8:45 show)": { text: "A one-hour Candlelight concert of Halloween music played by the KalHaven String Quartet in a candlelit Wealthy Theatre. The program includes Thriller, the Beetlejuice, Addams Family, Halloween and Ghostbusters themes, Danse Macabre and Night on Bald Mountain; ages 8+.", source: "https://grcmc.org/theatre/event/candlelight-concert-a-haunted-evening-of-halloween-classics/1589" },
  "Willey Central – Acoustic Stew Music Guild": { text: "Willey Central (formerly Hickory Creek, founded in the 1970s) is the folk family band of Grand Rapids musician Andy Willey of The Willeys, with his siblings Rick, Rose and Bob. They play originals and covers on guitar, banjo, mandolin, fiddle and harmonica.", source: "https://grcmc.org/event/willey-central-acoustic-stew-music-guild/1737" },
  "Trillium Ballet: The Nutcracker": { text: "Trillium Ballet's ensemble performs The Nutcracker, the Christmas ballet about Clara, the Rat King and the Land of Sweets, with original choreography by Moriah Beth, Reuben Wilson and Hannah Terwin.", source: "https://grcmc.org/event/trillium-ballet-presents-the-nutcracker/1793" },
  "Finding Nemo JR. (Civic Theatre production, Mar 25–28)": { text: "A 60-minute stage musical of Pixar's Finding Nemo, with new songs by Kristen Anderson-Lopez and Robert Lopez, performed by students from Grand Rapids Civic Theatre's School of Theatre Arts. Rated G for the whole family.", source: "https://www.grct.org/findingnemojr/" },
  "Dancing With the Stars Live": { text: "The touring stage version of ABC's Dancing with the Stars, with an all-new show starring the TV series' pro dancers, including Val Chmerkovskiy, Jenna Johnson, Emma Slater and Alan Bersten, plus celebrity guests.", source: "https://dwtstour.com/" },
  "GR Symphony: Brahms & Wagner": { text: "Music Director Marcelo Lehninger leads the Grand Rapids Symphony in Brahms' Symphony No. 3, Wagner's Siegfried Idyll, and the Prelude and Liebestod from Tristan und Isolde with mezzo-soprano Michelle DeYoung.", source: "https://www.grsymphony.org/brahmswagner" },
  "GR Symphony: Capriccio espagnol": { text: "Marcelo Lehninger leads the Grand Rapids Symphony in a Spanish-flavored program, with violinist Nathan Amaral as soloist in Henrique Oswald's Violin Concerto, plus music by Falla and Óscar Navarro.", source: "https://assets.speakcdn.com/assets/2216/grand_rapids_symphony_2026_2027_season_brochure.pdf" },
  "GR Symphony: Celebrating Beethoven": { text: "An all-Beethoven program led by Marcelo Lehninger: the Egmont Overture, the \"Emperor\" Piano Concerto with pianist Evren Ozel, and Symphony No. 7.", source: "https://www.grsymphony.org/celebrate-beethoven" },
  "GR Symphony: Brahms' Double Concerto": { text: "Guest conductor JoAnn Falletta leads the Grand Rapids Symphony, with the orchestra's own James Crawford (violin) and Alicia Eppinga (cello) in Brahms' Double Concerto. The program also has Hailstork's Fanfare on Amazing Grace and Schumann's \"Rhenish\" Symphony.", source: "https://www.grsymphony.org/double-concerto" },
  "GR Symphony: Barber & Bernstein": { text: "Marcelo Lehninger leads an all-American program: Missy Mazzoli's These Worlds in Us, Barber's Second Essay for Orchestra, and Bernstein's Symphony No. 2, \"The Age of Anxiety,\" with pianist Andrew von Oeyen and mezzo-soprano Michelle DeYoung.", source: "https://www.grsymphony.org/barber-bernstein" },
  "GR Symphony: Coffee with Pearl (GR Symphony Chorus)": { text: "A morning concert by the Grand Rapids Symphony Chorus led by conductor Pearl Shangkuan, with choral music by J.S. Bach, Dan Forrest, Elaine Hagenberg and more. Coffee and doughnuts are available before the concert.", source: "https://www.scmcgr.org/concerts" },
  "GR Symphony: Light Beyond Shadows (GR Symphony Chorus)": { text: "Conductor Pearl Shangkuan and the Grand Rapids Symphony Chorus perform choral music by J.S. Bach, Dan Forrest, Elaine Hagenberg and more.", source: "https://www.scmcgr.org/concerts" },
  "GR Symphony: Coffee with Marcelo (Mary Beth Orr, horn)": { text: "A morning concert with Music Director Marcelo Lehninger and Grand Rapids Symphony hornist Mary Beth Orr, featuring Mozart's Symphony No. 40 and a Symphony commission by Lydia Busler. Coffee and doughnuts are available before the concert.", source: "https://www.scmcgr.org/concerts" },
  "GR Symphony: Mozart & Busler! (Mary Beth Orr, horn)": { text: "Music Director Marcelo Lehninger and Grand Rapids Symphony hornist Mary Beth Orr in a program featuring Mozart's Symphony No. 40 and a Symphony commission by Lydia Busler.", source: "https://www.scmcgr.org/concerts" },
  "Phabies + Ohly + Kate Pillsbury": { text: "Phabies is a five-piece alternative band from Grand Rapids led by songwriter Laura Hobson, blending '60s-style folk with pop and indie. Their albums are Fire Seed (2022) and The Curse Of Caring (2025), which won Album of the Year at the 2026 WYCE Jammies.", source: "http://phabies.com/epk" },
  "Prior Noon (Hometown Stache Bash)": { text: "Prior Noon is a West Michigan country band formed in 2020, fronted by singer McKenna Grody. They've opened for Jon Pardi, Gabby Barrett and LoCash, and their 2024 single \"What You're Thinking\" reached the Music Row Country Breakout chart's Top 100.", source: "https://www.priornoon.com/" },
  "Dark Divine": { text: "Dark Divine is a horror-themed hard rock band from Orlando, Florida, known for singles like \"Circles\" and \"Run Away.\" Fire From The Gods, Outlier and Never Enough open.", source: "https://sectionlive.com/event/dark-divine/the-stache/grand-rapids-michigan/" },
  "The Insiders: Tribute to Tom Petty with Kait Rose & Co: Fleetwood Magic": { text: "A tribute double bill: Kait Rose & Co. open at 7pm as Fleetwood Magic, playing Fleetwood Mac, followed by The Insiders playing the music of Tom Petty.", source: "https://thebigroomgr.com/event/the-insiders-tribute-to-tom-petty-with-kait-rose-co-fleetwood-magic/" },
  "Flamingosis – Bright Moments 10th Anniversary (with Pablo Eskobear, Drop Catch)": { text: "Flamingosis is a producer of sample-based music that mixes hip-hop and funk. This tour marks 10 years since his album Bright Moments (July 2016).", source: "https://flamingosis1.bandcamp.com/album/bright-moments" },
  "The Skies Revolt + Still.Teddy + Glassfield + From The Fleet": { text: "The Skies Revolt is a Grand Rapids post-hardcore/indie rock band that started in 2004; their studio album Some Kind of Cosmonaut came out in 2012.", source: "https://en.wikipedia.org/wiki/The_Skies_Revolt" },
  "Greylan James": { text: "Greylan James is a Knoxville-raised, Nashville-based country singer-songwriter and ACM Award winner. He has written songs recorded by Kenny Chesney, Morgan Wallen, Cole Swindell and Darius Rucker.", source: "https://www.greylanjames.com/about/" },
  "Chicks in the Office – The Just Between Us Tour (18+)": { text: "A live, pajama-dress-code \"sleepover\" show with Ria and Fran of Chicks in the Office: laughs, pop culture, games and special guests.", source: "https://sectionlive.com/event/chicks-in-the-office-the-just-between-us-tour/the-intersection/grand-rapids-michigan/" },
  "Clap Your Hands Say Yeah": { text: "Clap Your Hands Say Yeah is a US indie rock band active since the early 2000s, founded by singer-songwriter Alec Ounsworth, who now performs under the name as a solo artist. The band first gained attention through MP3 blogs and is seen as a defining band of the blog-rock era.", source: "https://en.wikipedia.org/wiki/Clap_Your_Hands_Say_Yeah" },
  "Carsie Blanton": { text: "Carsie Blanton is an American singer-songwriter and activist based in New Jersey. She has released ten full-length albums and three EPs and tours regularly across North America and Europe.", source: "https://en.wikipedia.org/wiki/Carsie_Blanton" },
  "Judy Collins – Sweet Judy Blue Eyes: Farewell": { text: "Judy Collins is an American singer-songwriter with a career spanning nearly seven decades, known for the clarity of her voice and her social activism. This stop is part of her \"Sweet Judy Blue Eyes\" Farewell Tour, her final run on the road.", source: "https://www.scmcgr.org/concerts/judy-collins-2027" },
  "Stick Figure – Enjoy the Ride Tour (with The Elovaters, Harry Mack)": { text: "Stick Figure is an American reggae band founded in 2005 by frontman and multi-instrumentalist Scott Woodruff, who writes, records and produces nearly all of its music. Special guests are The Elovaters and Harry Mack.", source: "https://en.wikipedia.org/wiki/Stick_Figure" },
  "Greta Van Fleet – Into the Beginning Tour (with Portugal. The Man, Friko)": { text: "Greta Van Fleet is a rock band formed in 2012 in Frankenmuth, Michigan, made up of the Kiszka brothers (Josh, Jake and Sam) and drummer Danny Wagner. Their debut single \"Highway Tune\" topped Billboard's Mainstream Rock chart in 2017. Support is from Portugal. The Man and Friko.", source: "https://en.wikipedia.org/wiki/Greta_Van_Fleet" },
  "Matchbox Twenty – 30th Anniversary Live Tour (with Matt Nathanson)": { text: "Matchbox Twenty is an American rock band formed in 1995 in Orlando, Florida, fronted by Rob Thomas. Their hits include \"Bent,\" \"If You're Gone,\" \"Unwell\" and \"How Far We've Come.\" Special guest is Matt Nathanson.", source: "https://www.acrisureamphitheater.com/events/2027/matchbox-twenty" },
  "Eric Andre: Subtle": { text: "Eric André is an American comedian, actor and TV host, best known as creator and host of Adult Swim's surreal comedy series The Eric Andre Show (2012–2023).", source: "https://en.wikipedia.org/wiki/Eric_Andr%C3%A9" },
  "Broadway Grand Rapids: The Phantom of the Opera (Aug 11–22)": { text: "Andrew Lloyd Webber's musical, inspired by Gaston Leroux's 1910 novel, about soprano Christine Daaé and the disfigured musical genius who haunts the Paris Opera House. This is the revitalized Cameron Mackintosh touring production, with songs like \"The Music of the Night\" and \"All I Ask of You.\"", source: "https://www.devosperformancehall.com/events/2027/broadway-grand-rapids-presents-phantom-of-the-opera" },
  "Steve Hofstetter": { text: "Steve Hofstetter is an American stand-up comedian and podcast host with a large YouTube following. He has hosted Laughs on Fox stations and been a panelist on MLB Network's MLB Now.", source: "https://en.wikipedia.org/wiki/Steve_Hofstetter" },
  "World Famous POPOVICH Comedy Pet Theater": { text: "A family show combining animal and human performers in comedy skits with clowns, acrobatics, juggling and stunts, directed by creator Gregory Popovich.", source: "https://en.wikipedia.org/wiki/Popovich_Comedy_Pet_Theater" },
  "Candlelight: Queen vs. The Beatles (Jan 15)": { text: "A one-hour Candlelight concert at a candlelit Wealthy Theatre, with the music of Queen and The Beatles played live in a multi-sensory setting. Ages 8+; doors open 45 minutes before and late entry isn't allowed.", source: "https://grcmc.org/theatre/event/candlelight-tribute-to-queen-and-the-beatles/1729" },
  "Candlelight: Queen vs. The Beatles (Feb 5)": { text: "A one-hour Candlelight concert at a candlelit Wealthy Theatre, with the music of Queen and The Beatles played live in a multi-sensory setting. Ages 8+; doors open 45 minutes before and late entry isn't allowed.", source: "https://grcmc.org/theatre/event/candlelight-tribute-to-queen-and-the-beatles/1705" },
  "Candlelight: 90s Hip-Hop on Strings": { text: "A one-hour Candlelight concert at a candlelit Wealthy Theatre, with the music of 90s hip-hop played live in a multi-sensory setting. Ages 8+; doors open 45 minutes before and late entry isn't allowed.", source: "https://grcmc.org/event/candlelight-90s-hip-hop-on-strings/1730" },
  "Candlelight: Tribute to Michael Jackson": { text: "A one-hour Candlelight concert at a candlelit Wealthy Theatre, with the music of Michael Jackson played live in a multi-sensory setting. Ages 8+; doors open 45 minutes before and late entry isn't allowed. A tribute, not affiliated with the artist or his estate.", source: "https://grcmc.org/event/candlelight-tribute-to-michael-jackson/1708" },
  "Candlelight: Coldplay & Imagine Dragons": { text: "A one-hour Candlelight concert at a candlelit Wealthy Theatre, with the music of Coldplay and Imagine Dragons played live in a multi-sensory setting. Ages 8+; doors open 45 minutes before and late entry isn't allowed.", source: "https://grcmc.org/theatre/event/candlelight-concert-coldplay-imagine-dragons/1709" },
  "Candlelight: Valentine's Day Special": { text: "A one-hour Valentine's Day Candlelight concert at a candlelit Wealthy Theatre, with live music in a multi-sensory setting. Ages 8+; doors open 45 minutes before and late entry isn't allowed.", source: "https://grcmc.org/event/candlelight-valentine-s-day-special/1731" },
  "Josh Rose & Drew Nelson – Acoustic Stew Music Guild": { text: "Josh Rose and Drew Nelson are West Michigan traditional Americana and folk musicians, described by the Acoustic Stew Music Guild as the finest of the region's second generation of acoustic players.", source: "https://grcmc.org/event/josh-rose-drew-nelson-acoustic-stew-music-guild/1742" },
  "Hawks and Owls String Band – Acoustic Stew Music Guild": { text: "Hawks and Owls String Band plays \"Old Timey\" fiddle tunes, country blues and old-school bluegrass. Fiddler/mandolinist Bruce Ling shares the history of the songs, joined by Becca Ling, Austin Benzing and Jerry Wenger.", source: "https://grcmc.org/event/hawks-and-owls-string-band-acoustic-stew-music-guild/1738" },
  "Blue Water Ramblers – Acoustic Stew Music Guild": { text: "The Blue Water Ramblers are a five-piece Americana/roots band formed in 2004 by Banjo-Jim Foerch and Bear Berends, playing originals and covers in a traditional folk style.", source: "https://grcmc.org/event/blue-water-ramblers-acoustic-stew-music-guild/1740" },
  "Ruth & Max Bloomquist – Acoustic Stew Music Guild": { text: "Singer-songwriter Ruth Bloomquist and Max Bloomquist on harmony vocals and upright bass play acoustic Americana/folk with folk, bluegrass and country influences.", source: "https://grcmc.org/event/ruth-max-bloomquist-acoustic-stew-music-guild/1743" },
  "The Huey Lewis and the News Experience": { text: "The Transit Brothers' theatrical tribute to Huey Lewis and the News, with songs like \"The Power of Love,\" \"Hip to Be Square\" and \"Back in Time,\" plus horns, comedy, video and audience interaction.", source: "https://grcmc.org/event/the-huey-lewis-and-the-news-experience/1668" },
  "The Blues Brothers Experience": { text: "The Transit Brothers' high-energy theatrical tribute to the Blues Brothers, with a live band playing classics like \"Soul Man,\" \"Gimme Some Lovin'\" and \"Sweet Home Chicago.\"", source: "https://grcmc.org/event/the-blues-brothers-experience-1/1669" },
  "Pop Scholars: Improv Comedy (Feb 6)": { text: "Pop Scholars is an improv comedy troupe performing fast-paced, made-up-on-the-spot scenes that invite the audience in on the show.", source: "https://www.popscholars.com/" },
  "Pop Scholars: Improv Comedy (Dec 5)": { text: "Pop Scholars is an improv comedy troupe performing fast-paced, made-up-on-the-spot scenes that invite the audience in on the show.", source: "https://www.popscholars.com/" },
  "Pop Scholars: Improv Comedy (Mar 6)": { text: "Pop Scholars is an improv comedy troupe performing fast-paced, made-up-on-the-spot scenes that invite the audience in on the show.", source: "https://www.popscholars.com/" },
  "Pop Scholars: Improv Comedy (Jan 9)": { text: "Pop Scholars is an improv comedy troupe performing fast-paced, made-up-on-the-spot scenes that invite the audience in on the show.", source: "https://www.popscholars.com/" },
  "Pop Scholars: Improv Comedy (Apr 17)": { text: "Pop Scholars is an improv comedy troupe performing fast-paced, made-up-on-the-spot scenes that invite the audience in on the show.", source: "https://www.popscholars.com/" },
  "SPITE – New World Killer Tour": { text: "SPITE is a deathcore band formed in California's Bay Area, blending death metal, metalcore and nu-metal. After signing with Rise Records they released Dedication to Flesh in 2022. Support comes from Stick To Your Guns, No Cure and Vomit Forth.", source: "https://sectionlive.com/event/spite-new-world-killer-tour/elevation/grand-rapids-michigan/" },
  "Autumn Weekends Live Music: Selkie (included with admission)": { text: "Selkie are Celtic multi-instrumentalists playing a Samhain-themed set of lively traditional tunes and irreverent songs of madness, fairies and ghosts.", source: "https://www.meijergardens.org/events/autumn-weekends-live-music-with-selkie/?occurrence=2026-10-24" },
  "Autumn Weekends Live Music: The Fall Upwards Duo (included with admission)": { text: "Dede Alder (vocalist, percussionist and songwriter with the Earthwork Music Collective) and Ugandan guitarist and pianist Ivan Akansiima, blending jazz, world music, folk and improvisation.", source: "https://www.meijergardens.org/events/autumn-weekends-live-music-with-the-fall-upwards-duo/?occurrence=2026-10-25" },
  "Autumn Weekends Live Music: The Morning Yells (included with admission)": { text: "The Morning Yells are a Grand Rapids alt-country band led by siblings Phil and Laura Stancil, formed in 2017. They have released two LPs and two EPs.", source: "https://www.meijergardens.org/events/autumn-weekends-live-music-with-the-morning-yells/?occurrence=2026-10-31" },
  "Haggis X-1": { text: "Haggis X-1 is a high-energy Celtic rock band built around veteran members of the Canadian group Enter the Haggis (Craig Downie, Trevor Lewington and Tom Barraco), known for songs like \"One Last Drink\" and \"Down With The Ship\".", source: "https://www.themidtowngr.com/shows-events/detail/Haggis-X-1" },
  "After Dark: Smooth Jazz Sessions": { text: "An evening of contemporary smooth jazz opened by Grand Rapids saxophonist, composer and bandleader Isaac Norris, whose music blends jazz, R&B, funk and neo-soul.", source: "https://www.themidtowngr.com/shows-events/detail/After-Dark-Smooth-Jazz-Sessions" },
  "(Nolan Patin is) Elvira: Live on the Big Scream! (7 & 10 PM shows)": { text: "A 90-minute, 18+ one-performer comedy show starring Nolan Patin as Elvira, with 80s horror film reviews, audience participation and a costume contest.", source: "https://www.betkapopeproductions.com/elvira" },
  "Free Show: Mickey & The Heartthrobs + Secret Satan (no cover, 21+)": { text: "Mickey & The Heartthrobs are a post-punk band from Grand Rapids; Secret Satan play heavy rock from West Michigan.", source: "https://speciationartisanales.com/events/matht-ss" },
  "Free Halloween Show: Garbage Angel (no cover, 21+)": { text: "Garbage Angel is a Halloween band that started in an Eastown back yard in Grand Rapids and now brings its spooky party all over West Michigan. Costumes encouraged.", source: "https://speciationartisanales.com/events/garbageangel-oct-2026" },
  "Jazz Jam w/ Tommy Pancy (Oct 25)": { text: "Grand Rapids saxophonist and MSU jazz alum Tommy Pancy hosts a weekly Sunday jazz jam that opens with a house band set, then a sign-up queue for players of all skill levels, rooted in jazz standards.", source: "https://speciationartisanales.com/events/jazz-jam-10-25" },
  "Jazz Jam w/ Tommy Pancy (Nov 1)": { text: "Grand Rapids saxophonist and MSU jazz alum Tommy Pancy hosts a weekly Sunday jazz jam that opens with a house band set, then a sign-up queue for players of all skill levels, rooted in jazz standards.", source: "https://speciationartisanales.com/events/jazz-jam-11-1" },
  "Free Show Friday: The Moonrays (no cover)": { text: "The Moonrays play a blend of retro surf, cosmic blues and atomic rock, and appear at Speciation the last Friday of every month.", source: "https://speciationartisanales.com/events/the-moonrays-fun-times-in-space-2026-oct" },
  "Capella Fall Concert: Come Home (free)": { text: "Calvin University's Capella choir performs sacred works, folk songs, spirituals and contemporary choral favorites from around the world.", source: "https://calvin.edu/events/capella-fall-concert-come-home-1793403000" },
  "Chloe Kimes wsg Rowdy Fingers": { text: "Chloe Kimes is a Nashville-based independent Americana singer-songwriter who grew up on the lakeshore of West Michigan. Her album Daredevil came out October 16, 2026.", source: "https://www.ticketweb.com/event/chloe-kimes-rowdy-fingers-tip-top-deluxe-bar-tickets/15036843" },
  "Pipe Screams Organ Concert": { text: "A Halloween organ concert in the Fountain Street Church sanctuary: organists Noah Smith, Larry Visser, Rob Hobgood and other local favorites play in costume, with dramatic classics, eerie film scores and seasonal favorites. Costumes are encouraged for all ages.", source: "https://fountainstreet.churchcenter.com/calendar/event/238246591" },
  "Bach Chorale of Grand Rapids: Fall Charity Concert (with pianist Alan Chiang)": { text: "The Bach Chorale of Grand Rapids, led by artistic director Martin Werner, performs with guest pianist Alan Chiang: Busoni's arrangement of Bach's Chaconne in D Minor, Bach's Concerto in F Major (BWV 1057), Mozart and sacred choral works. Part of the proceeds goes to Fountain Street Church's Community Assistance Fund.", source: "https://www.tickettailor.com/events/fountainstreetchurch/2415882" },
  "Resting Witch Face - 2026 Halloween Sketch Comedy Show (Oct 23–30)": { text: "The Comedy Project's annual Halloween sketch comedy show, written and performed by its local cast.", source: "https://www.crowdwork.com/e/resting-witch-face-2026-halloween-sketch-comedy-show" },
  "Dom Flemons wsg Myron Elkins (Solo Acoustic)": { text: "Dom Flemons, \"The American Songster,\" is a singer, songwriter and multi-instrumentalist who plays old-time music, Piedmont blues and traditional country. He has performed with Taj Mahal, Old Crow Medicine Show, Mike Seeger and others.", source: "https://en.wikipedia.org/wiki/Dom_Flemons" },
  "The Surfrajettes wsg Kitten and the Tonics": { text: "The Surfrajettes are an instrumental surf rock band from Toronto.", source: "https://en.wikipedia.org/wiki/The_Surfrajettes" },
  "Scott H. Biram": { text: "Scott H. Biram, \"The Dirty Old One Man Band,\" is a one-man-band musician mixing blues, punk and outlaw country. He has played The Tonight Show with Jay Leno and venues from CBGB to Lincoln Center.", source: "https://en.wikipedia.org/wiki/Scott_H._Biram" },
  "Possessed By Paul James with Coleman Williams": { text: "Possessed by Paul James is the stage name of Konrad Wert, a folk singer-songwriter from Florida who plays banjo, guitar and fiddle with roots in folk, blues and punk.", source: "https://en.wikipedia.org/wiki/Possessed_by_Paul_James" },
  "Whitehorse": { text: "Whitehorse is a Canadian folk-roots duo from Hamilton, Ontario: husband and wife Luke Doucet and Melissa McClelland, both established singer-songwriters before teaming up.", source: "https://en.wikipedia.org/wiki/Whitehorse_(band)" },
  "Luke Winslow-King": { text: "Luke Winslow-King is a guitarist and singer known for his slide guitar, playing vintage blues and jazz shaped by his 15 years in New Orleans.", source: "https://en.wikipedia.org/wiki/Luke_Winslow-King" },
  "Mike Zito": { text: "Mike Zito is a blues-rock guitarist, singer, songwriter and producer from St. Louis, and a co-founder of Royal Southern Brotherhood.", source: "https://en.wikipedia.org/wiki/Mike_Zito" },
  "Charlie Berens – The Lost and Found": { text: "Charlie Berens is a comedian and journalist best known for his online series Manitowoc Minute; his humor centers on the Midwest.", source: "https://en.wikipedia.org/wiki/Charlie_Berens" },
  "Jazz Jam w/ Tommy Pancy (Nov 8)": { text: "Grand Rapids saxophonist and MSU jazz alum Tommy Pancy hosts a weekly Sunday jazz jam that opens with a house band set, then a sign-up queue for players of all skill levels, rooted in jazz standards.", source: "https://speciationartisanales.com/events/jazz-jam-11-8" },
  "Free Show Friday: The Moonrays (Nov 27, no cover)": { text: "The Moonrays play a blend of retro surf, cosmic blues and atomic rock, and appear at Speciation the last Friday of every month.", source: "https://speciationartisanales.com/events/the-moonrays-fun-times-in-space-2026-nov" },
  "Born With Teeth (by Liz Duffy Adams; Wealthy Annex, Nov 12–14 & 19–21)": { text: "A two-person play by Liz Duffy Adams: Kit Marlowe and a young Will Shakespeare meet in the back room of a pub to write a history play cycle under a repressive regime. Directed by Nicole Noble, with Mae Fletcher and Lindsey Hansen.", source: "https://grcmc.org/event/born-with-teeth/1756" },
  "Phoebe in Winter (Actors' Theatre, May 6–15)": { text: "A play by Jen Silverman: three brothers come home from a distant war, and a young woman named Phoebe arrives saying they killed her three brothers. She doesn't want money or an apology; she wants them to become her family. Directed by Jason J. Flannery.", source: "https://actorstheatregrandrapids.org/programming/coming-soon/phoebe-in-winter/" },
  "Pizza Bagels (Jewish Theatre Grand Rapids, Jun 10–20)": { text: "A play by Matthew Libby about two Jewish Italian families thrown together by a DNA matching website, and what happens when your sense of who you are is turned upside down. Directed by Pamela Steers.", source: "https://www.jtgr.org/season" },
  "Les Misérables (Civic Theatre production, Jun 4–20)": { text: "Grand Rapids Civic Theatre closes its centennial season with the musical based on Victor Hugo's novel: Jean Valjean breaks parole to start a new life and is hunted by Inspector Javert through the Paris uprising of 1832.", source: "https://www.grct.org/lesmiserables/" },
  "Short Circuit (Jewish Theatre Grand Rapids, Apr 15–May 2)": { text: "A play by Noa Lazar Keinan about the zany, funny, and sensitive ways a husband and wife cope with raising an autistic five-year-old. Directed by GM (Bud) Thompson for Jewish Theatre Grand Rapids at Dog Story Theater.", source: "https://www.jtgr.org/2026-2027/short-circuit" },
  "The Verve Pipe (SOLD OUT)": { text: "The Verve Pipe is a Michigan alternative rock band formed in East Lansing in 1992 and led by singer-songwriter Brian Vander Ark. They broke through nationally with their multi-platinum 1996 album Villains and the hit single \"The Freshmen.\"", source: "https://en.wikipedia.org/wiki/The_Verve_Pipe" },
  "PTOM Halloween Costume Party ft. IONS (Tool Tribute) + 9 Acts": { text: "Park Theatre Open Mic's annual Halloween Costume Party in downtown Holland, headlined by West Michigan Tool tribute band IONS alongside nine local acts.", source: "https://parktheatreholland.org/" },
  "The Rocky Horror Picture Show (Park Theatre)": { text: "A Halloween-week screening and interactive celebration of the 1975 cult musical comedy horror film The Rocky Horror Picture Show at historic Park Theatre in downtown Holland.", source: "https://en.wikipedia.org/wiki/The_Rocky_Horror_Picture_Show" },
  "Trixy Tang + Boys Gone Mild: Rock N Roll Halloween Costume Party": { text: "A rock-and-roll Halloween costume party featuring West Michigan classic-rock and party band Trixy Tang with Boys Gone Mild.", source: "https://parktheatreholland.org/" },
  "Revolución De Amor (Maná Tribute) + Grupo Super Nova: Fiesta de Halloween": { text: "A Halloween night Latin rock and dance fiesta at Park Theatre featuring Revolución De Amor, a tribute to Mexican rock legends Maná, plus Grupo Super Nova.", source: "https://parktheatreholland.org/" },
  "The Soul Syndicate – Funk, Soul, Disco & R&B": { text: "The Soul Syndicate is a West Michigan horn-driven band performing classic funk, soul, Motown favorites, disco and R&B dance hits.", source: "https://parktheatreholland.org/" },
  "The Traveling Wilburys Revue": { text: "A live tribute celebrating the 1980s supergroup The Traveling Wilburys (George Harrison, Bob Dylan, Tom Petty, Roy Orbison and Jeff Lynne), performing hits like \"Handle with Care\" and \"End of the Line\" plus solo classics from each member.", source: "https://parktheatreholland.org/" },
  "Kevin Farley": { text: "Kevin Farley is a stand-up comedian and actor (and brother of the late Chris Farley) who trained at Chicago's Second City and has appeared in films like The Waterboy and Black Sheep as well as Netflix's F Is for Family.", source: "https://en.wikipedia.org/wiki/Kevin_Farley" },
  "Big Shrimp – Fall Tour 2026 w/ Tiberius": { text: "Big Shrimp is a progressive rock and improvisational jam band from Rochester, New York, touring with opener Tiberius.", source: "https://parktheatreholland.org/" },
  "’Stache Bash Fundraiser ft. Nate Holley": { text: "An afternoon community fundraiser concert at Park Theatre featuring West Michigan singer-songwriter and musician Nate Holley.", source: "https://parktheatreholland.org/" },
  "Slipknot + Godsmack Tribute Night: Tattered & Torn + Awaken wsg Leddj": { text: "A double-bill hard rock and metal tribute night featuring Tattered & Torn (Slipknot tribute) and Awaken (Godsmack tribute) with special guest Leddj.", source: "https://parktheatreholland.org/" },
  "Chart Attack: The Punk Rock Party Band": { text: "Chart Attack is a five-piece punk rock party band playing high-energy pop-punk and alternative rock anthems.", source: "https://parktheatreholland.org/" },
  "Full Cord & Roosevelt Diggs": { text: "A co-headlining night of Michigan bluegrass, folk and Americana: Full Cord won the 2022 Telluride Bluegrass Band Competition, and Roosevelt Diggs is a West Michigan roots and Americana band.", source: "https://parktheatreholland.org/" },
  "PTOM + Hunter Miles Present: A Comedy Show Vol. 4": { text: "A Thanksgiving-weekend stand-up comedy showcase hosted by Park Theatre Open Mic and comedian Hunter Miles, featuring Michigan comics.", source: "https://parktheatreholland.org/" },
  "Tom Arnold – Live Stand-Up Comedy": { text: "Tom Arnold is a stand-up comedian, actor and writer known for True Lies, Roseanne, The Best Damn Sports Show Period and Sons of Anarchy.", source: "https://en.wikipedia.org/wiki/Tom_Arnold_(actor)" },
  "Spafford wsg Act Casual": { text: "Spafford is an improvisational rock and electro-funk jam band formed in Prescott, Arizona, in 2009, joined by Detroit jam quartet Act Casual.", source: "https://en.wikipedia.org/wiki/Spafford_(band)" },
  "Winter Jazz by Holland Concert Jazz Orchestra (Dutch Winterfest)": { text: "A Dutch Winterfest big-band holiday concert by the Holland Concert Jazz Orchestra at Park Theatre, performing swinging arrangements of seasonal favorites.", source: "https://www.tuliptime.com/events/holland-concert-jazz-orchestra" },
  "MEGA 80's – Holland's Ultimate 80's Party": { text: "The Mega 80's are a Detroit-based 1980s retro party band that has headlined theatres and clubs across Michigan for over two decades with 80s pop, new wave and rock hits.", source: "https://parktheatreholland.org/" },
  "Story Spark: Gifts – A Moth-Inspired Storytelling Event": { text: "A live, Moth-inspired true storytelling evening at Park Theatre centered on the theme \"Gifts.\"", source: "https://parktheatreholland.org/" },
  "Joe Marcinek Band Plays the Grateful Dead": { text: "Indiana guitarist and songwriter Joe Marcinek leads a rotating collective of funk, jazz and jam musicians in an evening of Grateful Dead classics.", source: "https://parktheatreholland.org/" },
  "Dave Matthews Band + Pearl Jam Tributes: The Next Best of What's Around + Lemon Yellow Sons (Legends Series)": { text: "Kickoff to Park Theatre's 2027 Legends Series, pairing Dave Matthews Band tribute The Next Best of What's Around with Pearl Jam tribute Lemon Yellow Sons.", source: "https://parktheatreholland.org/" },
  "Ozzy Osbourne Tribute: Ozzy REbourne (Legends Series)": { text: "Ozzy REbourne performs the solo hits and Black Sabbath classics of heavy-metal icon Ozzy Osbourne as part of Park Theatre's 2027 Legends Series.", source: "https://parktheatreholland.org/" },
  "Eagles + Steve Miller Band Tributes: Trixy Tang + Klay N' The Mud (Legends Series)": { text: "Two West Michigan favorites team up for Park Theatre's 2027 Legends Series: Trixy Tang performing the harmonies and hits of the Eagles, and Klay N' The Mud celebrating the Steve Miller Band.", source: "https://parktheatreholland.org/" },
  "U2 + INXS Tributes: Without U2 + INXS Sensation (Legends Series)": { text: "A double tribute night in Park Theatre's 2027 Legends Series celebrating the arena rock of U2 (Without U2) and the Australian new-wave funk rock of INXS (INXS Sensation).", source: "https://parktheatreholland.org/" },
  "Michael Allman Band – Allman Brothers Celebration (Legends Series)": { text: "Michael Allman — the eldest son of Allman Brothers Band singer Gregg Allman — leads his band in an evening of Southern rock, blues and Allman Brothers classics.", source: "https://parktheatreholland.org/" },
  "RUSH Tribute: ANIMATION (Legends Series)": { text: "ANIMATION recreates the progressive rock catalog of Canadian trio Rush as part of Park Theatre's 2027 Legends Series.", source: "https://parktheatreholland.org/" },
  "Ahren Belisle – Live Stand-Up Comedy": { text: "Ahren Belisle is a software engineer and stand-up comedian living with cerebral palsy who uses his text-to-speech phone app to deliver comedy and became a finalist on Season 18 of America's Got Talent.", source: "https://parktheatreholland.org/" },
  "Pink Floyd Tribute: In the Flesh (Legends Series)": { text: "In the Flesh performs the classic albums and psychedelic rock anthems of Pink Floyd as part of Park Theatre's 2027 Legends Series.", source: "https://parktheatreholland.org/" },
  "Stevie Ray Vaughan Tribute: Texas Flood (Legends Series)": { text: "Dallas, Texas blues trio Texas Flood, led by guitarist and vocalist Tommy Katona, recreates the fiery Texas blues of Stevie Ray Vaughan and Double Trouble.", source: "https://parktheatreholland.org/" },
  "Talking Heads Tribute: Heads in Motion (SOLD OUT, Legends Series)": { text: "Heads in Motion performs the art-funk and new-wave classics of Talking Heads and Stop Making Sense as part of Park Theatre's 2027 Legends Series.", source: "https://parktheatreholland.org/" },
  "David Bowie Tribute: Blue Genies (SOLD OUT, Legends Series)": { text: "Blue Genies celebrate the glam-rock and pop catalog of David Bowie as part of Park Theatre's 2027 Legends Series.", source: "https://parktheatreholland.org/" },
  "Journey Tribute: The RockShow (SOLD OUT, Legends Series)": { text: "The RockShow performs the arena-rock hits of Journey as part of Park Theatre's 2027 Legends Series.", source: "https://parktheatreholland.org/" },
  "Led Zeppelin Tribute: Kashmir (SOLD OUT, Legends Series)": { text: "Chicago-based tribute band Kashmir recreates the live concerts and hard-rock catalog of Led Zeppelin as part of Park Theatre's 2027 Legends Series.", source: "https://parktheatreholland.org/" },
  "Powerman 5000 w/ Aesthetic Perfection + A Killer's Confession (SOLD OUT)": { text: "Powerman 5000 is an industrial rock and nu-metal band founded in 1991 by Spider One (younger brother of Rob Zombie), best known for their platinum 1999 album Tonight the Stars Revolt! and \"When Worlds Collide.\"", source: "https://en.wikipedia.org/wiki/Powerman_5000" },
  "Bingo Loco: Halloween (Holland Civic Center, 21+)": { text: "Bingo Loco turns traditional bingo into an interactive Halloween party with throwback music, dance-offs, lip-sync battles and prizes at Holland Civic Center Place (21+).", source: "https://hollandciviccenter.com/event/bingo-loco-3/" },
  "H2 Dance Company Fall Concert Series (Oct 30–31 & Nov 6–7, free with ticket)": { text: "Hope College's student company H2 Dance Co. performs contemporary, modern, jazz and tap works choreographed by faculty, guest artists and students at the historic Knickerbocker Theatre.", source: "https://calendar.hope.edu/event/h2-performances-8227" },
  "Hope College Orchestra Hymn Sing Concert": { text: "The Hope College Orchestra performs a fall concert and community hymn sing in the Concert Hall of the Jack H. Miller Center for Musical Arts.", source: "https://calendar.hope.edu/event/orchestra-concert" },
  "Laura Anglade (Great Performance Series)": { text: "Laura Anglade is a French-Canadian and Brooklyn-based jazz vocalist whose albums Venez Donc Chez Moi (Juno Award nominee) and Get Out of Town have earned appearances on The Late Show with Stephen Colbert and The Kelly Clarkson Show.", source: "https://hope.edu/news/2026/arts/hope-colleges-great-performance-series-announces-2026-27-season.html" },
  "Hope College Jazz Ensembles Concert": { text: "Hope College's student jazz ensembles perform big-band and small-group jazz standards and contemporary works at the Jack H. Miller Center.", source: "https://calendar.hope.edu/event/jazz-ensembles-concert" },
  "Hope College Concert Band Performance": { text: "The Hope College Concert Band performs classic and contemporary wind band repertoire at the Jack H. Miller Center for Musical Arts.", source: "https://calendar.hope.edu/event/concert-band-performance" },
  "Just in the Nick of Time (Holland Community Theatre, Dec 2–3, Dutch Winterfest)": { text: "A family-friendly holiday mystery play at Holland Community Theatre during Dutch Winterfest: Santa has gone missing right before Christmas, and the North Pole elves must solve the case.", source: "https://www.tuliptime.com/events/holland-community-theatre" },
  "Hope College Christmas Vespers (Dec 5 at 4:30 PM & Dec 6 at 3:00 PM)": { text: "A beloved Holland holiday tradition since 1941, Hope College's Christmas Vespers brings together hundreds of student musicians across choirs, orchestra and organ in Dimnent Memorial Chapel.", source: "https://calendar.hope.edu/event/christmas-vespers-3072" },
  "Michigan-IO Holiday Show (Dutch Winterfest)": { text: "Michigan-IO brings Great Lakes folk stories, acoustic instrumentation and holiday music to the Jack H. Miller Center as part of Holland's Dutch Winterfest.", source: "https://www.tuliptime.com/events/michigan-io" },
  "Camerata Nordica Octet (Great Performance Series)": { text: "Founded in Sweden in 1974, three-time Grammy-nominated chamber ensemble Camerata Nordica performs standing up and from memory in an octet of principal players.", source: "https://hope.edu/news/2026/arts/hope-colleges-great-performance-series-announces-2026-27-season.html" },
  "Actors from the London Stage: King Lear (Apr 8–9, Great Performance Series)": { text: "Founded by Sir Patrick Stewart in 1975, Actors from the London Stage brings five British classical actors to perform all 30 roles in William Shakespeare's tragedy King Lear.", source: "https://hope.edu/news/2026/arts/hope-colleges-great-performance-series-announces-2026-27-season.html" },
  "Chanticleer (Great Performance Series)": { text: "Founded in San Francisco in 1978, multi-Grammy-winning vocal ensemble Chanticleer — known as \"an orchestra of voices\" — performs repertoire spanning Renaissance polyphony, classical, gospel, jazz and pop.", source: "https://en.wikipedia.org/wiki/Chanticleer_(ensemble)" },
  "akeylah wellington: plastic-plastic — party!-party! (Opening Reception & Y2K Dance Party, free)": { text: "A free community celebration and 2000s-themed dance party at the Saugatuck Center for the Arts marking the opening of artist akeylah wellington's fall sculpture exhibition plastic-plastic.", source: "https://sc4a.org/event/plastic-plastic-party-party/" },
  "Mandolin with Brian Oberlin": { text: "Grand Rapids mandolinist, vocalist and educator Brian Oberlin performs an intimate 90-minute solo concert in the SCA listening room blending swing, bluegrass, Italian classical works and original compositions.", source: "https://sc4a.org/event/mandolin-with-brian-oberlin/" },
  "Jazz at the Cinema w/ Rufus Ferguson ft. Olivia Van Goor (Nov 13 at 7 PM & Nov 14 at 4 & 7 PM)": { text: "Pianist Rufus Ferguson and Detroit jazz vocalist Olivia Van Goor transform the SCA lobby into a jazz club for an evening of classic film-soundtrack standards like \"Singin' in the Rain,\" \"Over the Rainbow\" and \"Pure Imagination.\"", source: "https://sc4a.org/event/jazz-at-the-cinema/" },
  "MiniKiss (KISS Tribute, Wawyé Oasis)": { text: "MiniKiss is a little-person KISS tribute band founded by Joey Fatale in 1996, known for full KISS makeup, costumes and appearances in Dr Pepper commercials and television.", source: "https://gunlakecasino.com/entertainment/" },
  "The Rock Show (131 Sportsbar & Lounge)": { text: "The Rock Show performs classic arena rock hits live at Gun Lake Casino's 131 Sportsbar & Lounge.", source: "https://gunlakecasino.com/entertainment/" },
  "The Rocky Horror Picture Show (Wawyé Oasis at Gun Lake Casino)": { text: "An interactive Halloween-weekend presentation of the cult classic musical The Rocky Horror Picture Show inside Gun Lake Casino Resort's tropical Wawyé Oasis dome.", source: "https://gunlakecasino.com/entertainment/" },
  "Hairbanger's Ball – 80's Hair Rock (131 Sportsbar & Lounge)": { text: "Founded in Chicago in 2001, Hairbanger's Ball is one of the Midwest's most popular 1980s hair-metal tribute bands, playing Guns N' Roses, Mötley Crüe, Def Leppard, Poison and Bon Jovi.", source: "https://gunlakecasino.com/entertainment/" },
  "Halloween Pool Party (Wawyé Oasis)": { text: "A 21+ Halloween night DJ and pool party inside Gun Lake Casino Resort's glass-domed Wawyé Oasis.", source: "https://gunlakecasino.com/entertainment/" },
  "The Static Age – 90's & 00's Hits (131 Sportsbar & Lounge)": { text: "The Static Age performs 1990s and 2000s alternative rock and pop-punk hits for Halloween night at 131 Sportsbar & Lounge.", source: "https://gunlakecasino.com/entertainment/" },
  "Completely Unchained – Van Halen Tribute (Wawyé Oasis)": { text: "Completely Unchained is a tribute band recreating the David Lee Roth-era live shows and guitar fireworks of Van Halen.", source: "https://gunlakecasino.com/entertainment/" },
  "Thunder From Down Under (Nov 13 at 7 & 9 PM, Nov 14 at 8 PM; Wawyé Oasis)": { text: "Australia's Thunder From Down Under is the long-running Las Vegas male dance revue, performing three shows across two nights in Gun Lake Casino's Wawyé Oasis.", source: "https://gunlakecasino.com/entertainment/" },
  "Sushi Roll (131 Sportsbar & Lounge)": { text: "Sushi Roll is a high-energy West Michigan dance-rock and pop party band fronted by two powerhouse female vocalists.", source: "https://gunlakecasino.com/entertainment/" },
  "P.S. Dump Your Boyfriend (131 Sportsbar & Lounge)": { text: "P.S. Dump Your Boyfriend is a Chicago funk, soul and pop party band led by showman Dannyockett, mixing Prince, Michael Jackson, Bruno Mars and 90s dance hits.", source: "https://gunlakecasino.com/entertainment/" },
  "Jedi Mind Trip (131 Sportsbar & Lounge)": { text: "Jedi Mind Trip is a Michigan rock and party cover band performing classic rock, 80s and 90s hits.", source: "https://gunlakecasino.com/entertainment/" },
  "Sonimanic (131 Sportsbar & Lounge)": { text: "Sonimanic is a West Michigan rock and pop cover band performing hits from the 1980s through today.", source: "https://gunlakecasino.com/entertainment/" },
  "Rhymin' N Stealin' – Beastie Boys Tribute (Wawyé Oasis)": { text: "Rhymin' N Stealin' is the original Texas-based Beastie Boys tribute band, performing hip-hop and punk-rock classics like \"Sabotage,\" \"Fight for Your Right\" and \"Intergalactic.\"", source: "https://gunlakecasino.com/entertainment/" },
  "DJ Drew Behringer (131 Sportsbar & Lounge)": { text: "West Michigan open-format DJ Drew Behringer spins pop, dance and club hits at 131 Sportsbar & Lounge.", source: "https://gunlakecasino.com/entertainment/" },
  "Latin Night (Wawyé Oasis)": { text: "An evening of salsa, bachata, merengue and Latin dance music inside Gun Lake Casino Resort's Wawyé Oasis.", source: "https://gunlakecasino.com/entertainment/" },
  "Uncaged – Zac Brown Tribute (Wawyé Oasis)": { text: "Uncaged performs the harmonies, Southern rock and country hits of the Zac Brown Band, including \"Chicken Fried,\" \"Toes\" and \"Colder Weather.\"", source: "https://gunlakecasino.com/entertainment/" },
  "New Year's Eve DJ Pool Party (Wawyé Oasis)": { text: "Ring in 2027 inside Gun Lake Casino Resort's heated 80-degree Wawyé Oasis dome with live DJs, dancing and a midnight countdown.", source: "https://gunlakecasino.com/entertainment/" },
  "An Evening with Niko Moon (Wawyé Oasis)": { text: "Niko Moon is a country singer-songwriter from Tyler, Texas, who co-wrote five No. 1 hits for Zac Brown Band before breaking out solo with his double-platinum Billboard Hot Country Songs No. 1 hit \"Good Time.\"", source: "https://en.wikipedia.org/wiki/Niko_Moon" },
  "Sugarland – The Ride or Die Tour (21+)": { text: "Sugarland is the Grammy-winning country music duo of Jennifer Nettles and Kristian Bush, formed in Atlanta in 2002 and known for hits like \"Stay,\" \"Stuck Like Glue,\" \"All I Want to Do\" and \"Baby Girl.\"", source: "https://firekeeperscasino.com/shows/sugarland/" },
  "The All-American Rejects (21+)": { text: "Formed in Stillwater, Oklahoma, in 1999 and fronted by Tyson Ritter, The All-American Rejects are known for multi-platinum 2000s rock anthems including \"Swing, Swing,\" \"Dirty Little Secret,\" \"Move Along,\" \"It Ends Tonight\" and \"Gives You Hell.\"", source: "https://firekeeperscasino.com/shows/the-all-american-rejects/" },
  "Engelbert Humperdinck (21+)": { text: "British pop singer Engelbert Humperdinck has sold more than 140 million records worldwide over a 50+ year career, with timeless hits like \"Release Me,\" \"The Last Waltz,\" \"After the Lovin'\" and \"A Man Without Love.\"", source: "https://firekeeperscasino.com/shows/engelbert-humperdinck/" },
  "Tower of Power – Holiday & Hits Tour (21+)": { text: "Founded in Oakland, California, in 1968 by saxophonists Emilio Castillo and Stephen \"Doc\" Kupka, horn-driven funk and soul legends Tower of Power perform holiday favorites alongside hits like \"What Is Hip?\" and \"So Very Hard to Go.\"", source: "https://firekeeperscasino.com/shows/tower-of-power-holiday-hits-tour/" },
  "Revisiting Creedence (21+)": { text: "Fronted by former Creedence Clearwater Revisited members Dan McGuinness (vocals) and Kurt Griffey (lead guitar), Revisiting Creedence performs CCR classics like \"Proud Mary,\" \"Bad Moon Rising,\" \"Fortunate Son\" and \"Have You Ever Seen the Rain.\"", source: "https://firekeeperscasino.com/shows/revisiting-creedence/" },
  "Matt Mathews – Not What I Ordered World Tour (SOLD OUT, 8 & 10:30 PM shows)": { text: "Matt Mathews is a stand-up comedian, farmer, photographer and singer-songwriter from Birmingham, Alabama, who went viral with his \"Confessions with Matt\" segments and farm-life comedy.", source: "https://soaringeaglecasino.com/events/matt-mathews/" },
  "Wheel of Fortune LIVE! (Soaring Eagle)": { text: "The live touring stage edition of America's Game, where randomly selected audience members step onstage to spin a full-sized replica of the Wheel, solve puzzles and win trips or cash prizes up to $10,000.", source: "https://soaringeaglecasino.com/events/wheel-of-fortune-live/" },
  "Kenny G Live": { text: "Grammy-winning saxophonist Kenny G is the best-selling instrumental musician of the modern era, with more than 75 million records sold worldwide and hits like \"Songbird\" and \"Forever in Love.\"", source: "https://soaringeaglecasino.com/events/kenny-g/" },
  "Chicago Live in Concert": { text: "Rock and Roll Hall of Fame band Chicago — \"the rock and roll band with horns\" — has sold over 100 million records worldwide since 1967 with classics like \"25 or 6 to 4,\" \"Saturday in the Park\" and \"If You Leave Me Now.\"", source: "https://soaringeaglecasino.com/events/chicago/" },
  "HUNKS The Show": { text: "HUNKS The Show is a touring male dance revue with choreographed routines, music and light shows in Soaring Eagle's Entertainment Hall.", source: "https://soaringeaglecasino.com/events/hunks-the-show/" },
  "The Rockin' Holiday Bash ft. Hotel California (Eagles Tribute)": { text: "Soaring Eagle transforms its Entertainment Hall into a \"Martinis and Mistletoe\" holiday food and drink sampling festival featuring a live concert by Eagles tribute band Hotel California.", source: "https://soaringeaglecasino.com/events/the-rockin-holiday-bash/" },
  "Clint Black: Back on the Blacktop Tour wsg Collin Raye": { text: "Grammy-winning country icon Clint Black has sold over 20 million records and notched 22 No. 1 singles including \"Killin' Time\" and \"A Better Man,\" joined here by 90s country hitmaker Collin Raye (\"Love, Me\").", source: "https://soaringeaglecasino.com/events/clint-black/" },
  "Aaron Lewis and the Stateliners": { text: "Aaron Lewis, frontman of rock band Staind (\"It's Been Awhile\"), performs his chart-topping country catalog with his band The Stateliners.", source: "https://soaringeaglecasino.com/events/aaron-lewis/" },
  "Great White and Quiet Riot": { text: "A co-headlining night of 1980s hard rock and heavy metal: Great White (\"Once Bitten, Twice Shy,\" \"Rock Me\") and Quiet Riot (\"Cum On Feel the Noize,\" \"Metal Health\").", source: "https://soaringeaglecasino.com/events/great-white-and-quiet-riot/" },
  "Tom Segura: Preposterous": { text: "Tom Segura is one of comedy's top arena headliners, co-host of the podcasts Your Mom's House and 2 Bears, 1 Cave, and star of six Netflix stand-up specials including Sledgehammer and Teacher.", source: "https://soaringeaglecasino.com/events/tom-segura/" },
  "Riley Green – That's Just Me Tour (with Muscadine Bloodline, Jake Worthington & Hannah McFarland; Outdoors)": { text: "Alabama country singer-songwriter Riley Green (\"There Was This Girl,\" \"I Wish Grandpas Never Died,\" \"You Look Like You Love Me\") headlines Soaring Eagle's outdoor stage with Muscadine Bloodline, Jake Worthington and Hannah McFarland.", source: "https://soaringeaglecasino.com/events/riley-green-thats-just-me-tour-2027/" },
  "Michael Carbonaro: WONDERBOY": { text: "Magician, actor and comedian Michael Carbonaro — star of truTV's hidden-camera series The Carbonaro Effect and winner of the Academy of Magical Arts' Magician of the Year — brings his live stage magic and comedy tour WONDERBOY.", source: "https://fourwindscasino.com/newbuffalo/entertainment/event-center/" },
  "Wheel of Fortune LIVE! (Oct 31)": { text: "The live touring stage show of Wheel of Fortune, where audience members are selected to spin a full-sized replica of the Wheel, solve puzzles and win vacations or cash prizes up to $10,000.", source: "https://fourwindscasino.com/newbuffalo/entertainment/event-center/" },
  "Wheel of Fortune LIVE! (Nov 1 matinee)": { text: "Sunday matinee performance of the live touring stage show of Wheel of Fortune, where audience members spin the Wheel, solve puzzles and win prizes.", source: "https://fourwindscasino.com/newbuffalo/entertainment/event-center/" },
  "Rick Springfield": { text: "Grammy-winning Australian-American rocker and actor Rick Springfield has sold 25 million albums and scored 17 U.S. Top 40 hits including \"Jessie's Girl,\" \"Don't Talk to Strangers,\" \"An Affair of the Heart\" and \"Love Somebody.\"", source: "https://fourwindscasino.com/newbuffalo/entertainment/event-center/" },
  "Cirque Musica Holiday Wonderland": { text: "A family holiday spectacle combining cirque acrobatics, aerialists and high-flying stunts with beloved seasonal music at Four Winds' Silver Creek Event Center.", source: "https://fourwindscasino.com/newbuffalo/entertainment/event-center/" },
  "Chubby Checker – King of the Twist": { text: "Rock and Roll Hall of Famer Chubby Checker revolutionized pop music and dance floors in 1960 with \"The Twist\" — the only song to hit No. 1 on the Billboard Hot 100 in two separate chart runs — along with \"Let's Twist Again,\" \"Limbo Rock\" and \"The Fly.\"", source: "https://fourwindscasino.com/newbuffalo/entertainment/event-center/" },
  "Jefferson Starship and John Waite": { text: "Classic rock co-headliners Jefferson Starship (\"Jane,\" \"Miracles,\" \"Somebody to Love,\" \"We Built This City\") and singer-songwriter John Waite of The Babys and Bad English (\"Missing You,\" \"When I See You Smile\").", source: "https://fourwindscasino.com/newbuffalo/entertainment/event-center/" },
  "GRCC Kent Philharmonic Orchestra Concert (Royce Auditorium)": { text: "Founded in 1975 and conducted by Music Director Dr. Libor Ondras, the Kent Philharmonic Orchestra brings together Grand Rapids Community College students and West Michigan community musicians for four symphonic and concerto programs each academic year in Royce Auditorium at Saint Cecilia Music Center. Admission is $16 general ($10 for seniors, students and veterans; free for GRCC and GRPS students and children under 10).", source: "https://www.grcc.edu/events/grcc-music-presents-kent-philharmonic-orchestra-3" },
  "GRCC Choir Concert (Royce Auditorium)": { text: "Grand Rapids Community College's vocal ensembles — including the auditioned Concert Choir, Chamber Choir and open-enrollment College Choir led by Director of Choral Activities Dr. Andrew Martin — perform choral repertoire from the Renaissance through the 21st century in Royce Auditorium at Saint Cecilia Music Center. Tickets are $10 general admission ($5 for seniors and veterans; free for students and children under 10).", source: "https://www.grcc.edu/events/grcc-music-presents-choral-concert" },
  "GRCC Guitar Night: Grand Rapids Guitar Duo, Folias Duo & Student Ensembles": { text: "Hosted by the GRCC International Guitar Series and directed by Jonathan Marshall, GRCC Guitar Night features the Grand Rapids Guitar Duo, Folias Duo and GRCC Music student guitar ensembles in Linn Maxwell Keller Recital Hall at the Albert P. Smith Music Center. The October concert also includes a Halloween costume contest with two Ortega classical guitar giveaways.", source: "https://www.grcc.edu/events/grcc-music-presents-guitar-night-0" },
  "GRCC Campus Band and Wind Ensemble Concert (Royce Auditorium)": { text: "Directed by Dr. Shannon Shaker, Grand Rapids Community College's Wind Ensemble and community-open Campus Band perform classic and contemporary wind band repertoire in Royce Auditorium at Saint Cecilia Music Center. Admission is $10 general ($5 for seniors and veterans; free for students and children under 10).", source: "https://www.grcc.edu/events/grcc-music-presents-campus-band-wind-ensemble-concert" },
  "GRCC Student Honor Recital (free)": { text: "An afternoon recital in Linn Maxwell Keller Recital Hall at GRCC's Albert P. Smith Music Center showcasing solo and chamber performances by selected Grand Rapids Community College music students. Admission is free and open to the public.", source: "https://www.grcc.edu/events/grcc-music-presents-student-honor-recital" },
  "GRCC Flute Night with A/B Duo (free)": { text: "Grand Rapids Community College's Flute Ensemble — featuring C flutes, alto flutes, bass flutes and piccolos — shares the stage with guest artists A/B Duo in Linn Maxwell Keller Recital Hall at the Albert P. Smith Music Center. Admission is free.", source: "https://www.grcc.edu/events/grcc-music-presents-flute-night-ab-duo" },
  "GRCC Voice Area Recital (free)": { text: "Vocal music students from Grand Rapids Community College perform classical art songs, arias and musical theater selections in Linn Maxwell Keller Recital Hall at the Albert P. Smith Music Center. Admission is free.", source: "https://www.grcc.edu/events/grcc-music-presents-voice-area-recital-0" },
  "GRCC Percussion Area Recital (free)": { text: "GRCC percussion students and the GRCC Percussion Ensemble perform works for mallet instruments, timpani and chamber percussion in Linn Maxwell Keller Recital Hall at the Albert P. Smith Music Center. Admission is free.", source: "https://www.grcc.edu/events/grcc-music-presents-percussion-area-recital-0" },
  "Kent Philharmonic Orchestra Chamber Concert": { text: "Musicians from GRCC's Kent Philharmonic Orchestra, directed by Dr. Libor Ondras, present an intimate evening of string and wind chamber repertoire in Linn Maxwell Keller Recital Hall at the Albert P. Smith Music Center.", source: "https://www.grcc.edu/schools-departments/music/ensembles" },
  "GRCC Woodwind & Brass Area Recital (free)": { text: "Grand Rapids Community College woodwind and brass students perform solo and small-ensemble works in Linn Maxwell Keller Recital Hall at the Albert P. Smith Music Center. Admission is free.", source: "https://www.grcc.edu/events/grcc-music-presents-woodwind-brass-area-recital" },
  "GRCC Jazz Night": { text: "Directed by Dr. Shannon Shaker and Professor Jed Scott, GRCC's Jazz Ensemble, Jazz Combos and vocal jazz group Shades of Blue perform big-band swing, standards and contemporary jazz.", source: "https://www.grcc.edu/events/grcc-music-presents-jazz-night-1" },
  "GRCC Faculty Recital": { text: "Faculty artists from the Grand Rapids Community College Music Department perform solo and chamber works in Linn Maxwell Keller Recital Hall at the Albert P. Smith Music Center.", source: "https://www.grcc.edu/schools-departments/music" },
  "GRCC Flute Night": { text: "The GRCC Flute Ensemble — bringing together college students and community flutists on C flutes, alto flutes, bass flutes and piccolos — performs original arrangements and contemporary works in Linn Maxwell Keller Recital Hall.", source: "https://www.grcc.edu/schools-departments/music/ensembles" },
  "GRCC College Orchestra Concert": { text: "Conducted by Dr. Libor Ondras, the GRCC College Orchestra performs string and orchestral repertoire spanning baroque, classical and modern eras in Linn Maxwell Keller Recital Hall at the Albert P. Smith Music Center.", source: "https://www.grcc.edu/schools-departments/music/ensembles" },
  "GRCC Jazz Ensemble Concert": { text: "Led by Director of Bands Dr. Shannon Shaker, the auditioned GRCC Jazz Ensemble performs big-band charts, jazz standards and improvised solos in Linn Maxwell Keller Recital Hall.", source: "https://www.grcc.edu/schools-departments/music/ensembles" },
  "GRCC Honor Band 2027 Concert (Royce Auditorium)": { text: "Top high school wind and percussion musicians from across West Michigan join the GRCC Music Department for the annual GRCC Honor Band festival concert in Royce Auditorium at Saint Cecilia Music Center.", source: "https://www.grcc.edu/schools-departments/music/ensembles" },
  "GRCC International Guitar Series: Paloma Chaprnka": { text: "The GRCC International Guitar Series presents solo classical guitarist Paloma Chaprnka in concert at Linn Maxwell Keller Recital Hall in the Albert P. Smith Music Center. Tickets are $15 general admission ($10 for seniors and veterans; free for students and children under 10).", source: "https://www.grcc.edu/schools-departments/music" },
  "GRCC Piano Area Recital": { text: "Piano students from the Grand Rapids Community College Music Department perform solo classical and contemporary keyboard repertoire in Linn Maxwell Keller Recital Hall at the Albert P. Smith Music Center.", source: "https://www.grcc.edu/schools-departments/music" },
  "GRCC Music: PIANORAMA! 2027": { text: "GRCC Music's signature multi-pianist concert event brings students, faculty and guest pianists together for ensemble and duo-piano works in Linn Maxwell Keller Recital Hall at the Albert P. Smith Music Center.", source: "https://www.grcc.edu/schools-departments/music" },
  "GRCC String Night (free)": { text: "String students and chamber groups from Grand Rapids Community College, led by Dr. Libor Ondras, perform quartet and solo string repertoire in Linn Maxwell Keller Recital Hall. Admission is free.", source: "https://www.grcc.edu/schools-departments/music/ensembles" },
  "GRCC Composition and Recording Technology Showcase": { text: "Students in GRCC's Music Composition and Digital Audio / Recording Technology programs present original compositions and studio productions in Linn Maxwell Keller Recital Hall at the Albert P. Smith Music Center.", source: "https://www.grcc.edu/schools-departments/music" },
  "GRCC Trombone Choir Concert": { text: "Grand Rapids Community College's Trombone Choir — uniting GRCC students, dual-enrolled high school players and West Michigan community trombonists — performs brass ensemble repertoire in Linn Maxwell Keller Recital Hall.", source: "https://www.grcc.edu/schools-departments/music/ensembles" },
  "Schubert Male Chorus Christmas Concert: Snowprints in Song": { text: "Founded in Grand Rapids in 1883, the Schubert Male Chorus is one of the oldest men's glee clubs in the United States. Their 2026 holiday concert \"Snowprints in Song\" takes place in the Covenant Fine Arts Center Recital Hall at Calvin University.", source: "https://www.schubertmalechorus.org/concertsevents-calendar/" },
  "St. Cecilia Youth Philharmonic Winter Concert: Mozart Piano Concerto No. 12 (Royce Auditorium)": { text: "St. Cecilia Music Center's top youth orchestra, the Philharmonic, performs its winter concert in Royce Auditorium featuring the winner of SCMC's annual Piano Concerto Competition playing Mozart's Piano Concerto No. 12 in A Major (K. 414).", source: "https://www.scmcgr.org/school-of-music/youth-programs/concerto-competition" },
  "Grand Rapids Youth Symphony & Classical Orchestra 2026 Fall Concert": { text: "The Grand Rapids Youth Symphony & Classical Orchestra (GRYS & CO), the Grand Rapids Symphony's auditioned youth ensembles, open their 2026–27 season with a program played by several of their student orchestras. This fall concert moves out of downtown to the Northview Performing Arts Center on the city's northeast side.", source: "https://www.grysco.org/concerts" },
  "Calvin Theatre Company Lab Series: An Evening with Ionesco": { text: "Calvin University's student theatre company pairs two classic one-acts by absurdist playwright Eugene Ionesco, The Bald Soprano and The Lesson, in Tina Howe's translation. Directed by John Scritchfield, the Lab Series production runs two nights in the Spoelhof University Center; tickets ($6–12) are sold through the Calvin box office.", source: "https://calvin.edu/events/calvin-theatre-company-lab-series-evening-ionesco-1801873800" },
  "Grand Rapids Youth Chorus Holiday Concert (4 PM)": { text: "Grand Rapids Youth Choruses brings all of its choirs, from Young Voices and Melodia through Mosaic Singers, Mandala and Youth Chorus, together for a holiday afternoon at Mayflower Congregational Church. Tickets go on sale about a month before the concert.", source: "https://gryouthchorus.org/event/holiday-concert-4pm/" },
  "Grand Rapids Youth Chorus Holiday Concert (7 PM)": { text: "The evening edition of Grand Rapids Youth Choruses' holiday program features its older ensembles, Mosaic Singers, Mandala and Youth Chorus, joined by the Alumni Plus group. Tickets go on sale about a month before the concert.", source: "https://gryouthchorus.org/event/holiday-concert-7pm/" },
  "Grand Rapids Youth Chorus Free Community Concert (free)": { text: "A free Saturday-morning concert at downtown's Park Congregational Church featuring the Young Voices, Melodia, Mosaic Singers and Mandala choirs of Grand Rapids Youth Choruses. No ticket is needed.", source: "https://gryouthchorus.org/event/free-community-concert-2/" },
  "Grand Rapids Youth Chorus at Second Reformed Church Concert Series": { text: "The Youth Chorus, the top ensemble of Grand Rapids Youth Choruses, appears as part of Second Reformed Church's concert series in downtown Zeeland.", source: "https://gryouthchorus.org/event/youth-chorus-at-second-reformed-church-concert-series/" },
  "Grand Rapids Youth Chorus: Mosaic Singers Composer Showcase": { text: "The Mosaic Singers of Grand Rapids Youth Choruses present a one-off composer showcase evening at Calvin University's Covenant Fine Arts Center.", source: "https://gryouthchorus.org/event/mosaic-singers-composer-showcase/" },
  "Calvin Theatre Company: The Miracle Worker": { text: "Calvin University's student theatre company stages William Gibson's Tony-winning drama about teacher Annie Sullivan and her young student Helen Keller, who lost her sight and hearing as a toddler. Directed by Brad Cain, the production runs two December weekends in Gezon Auditorium; tickets are $9–19 through the Calvin box office.", source: "https://calvin.edu/events/calvin-theatre-company-miracle-worker-1796430600" },
  "Grand Rapids Youth Symphony & Classical Orchestra Winter Concert (Piano Concerto Winner)": { text: "Affiliated with the Grand Rapids Symphony, the auditioned Grand Rapids Youth Symphony and Classical Orchestra perform advanced symphonic repertoire at DeVos Performance Hall, spotlighting the winner of the annual GRYS Piano Concerto Competition.", source: "https://www.grysco.org/concerts" },
  "Grand Rapids Youth Symphony & Classical Orchestra Spring Concert (Skip Gates Concerto Winners)": { text: "The Grand Rapids Youth Symphony and Classical Orchestra close their 2026–2027 season at DeVos Performance Hall with a program featuring the student soloists who won the Skip Gates Concerto Competition.", source: "https://www.grysco.org/concerts" },
  "Grand Rapids Youth Choruses: All Chorus Spring Concert (Royce Auditorium)": { text: "All five ensembles of the Grand Rapids Youth Choruses — Young Voices, Melodia, Mosaic Singers, Mandala and Youth Chorus — unite on stage in Royce Auditorium at Saint Cecilia Music Center for their 2026–2027 season finale.", source: "https://gryouthchorus.org/events/" },
  "Grand Rapids Women's Chorus Winter Concert": { text: "Celebrating its 31st season in Grand Rapids, the Grand Rapids Women's Chorus performs choral music centered on diversity, community and social justice at Fountain Street Church.", source: "https://grwc.org/" },
  "Grand Rapids Women's Chorus Cabaret: A Night at the Movies (5:00 & 8:00 PM shows)": { text: "The Grand Rapids Women's Chorus presents its annual cabaret evening — themed \"A Night at the Movies / Silver Screen Soiree\" — with 5:00 PM and 8:00 PM performances at Fountain Street Church.", source: "https://grwc.org/" },
  "Grand Rapids Women's Chorus Spring Concert (May 22 at 7:30 PM & May 23 at 3:00 PM)": { text: "The Grand Rapids Women's Chorus concludes its 31st season with two performances in Royce Auditorium at Saint Cecilia Music Center on Saturday evening and Sunday afternoon.", source: "https://grwc.org/" },
  "Battle Bots Improv Comedy Show": { text: "A 75-minute, fast-paced improv show performed by The Comedy Project's mainstage cast, built on audience suggestions. The venue pitches it to fans of short-form improv like Whose Line Is It Anyway and ComedySportz.", source: "https://www.crowdwork.com/e/battle-bots-improv-comedy-show" },
  "Midnight Society – Creepy Improv Comedy": { text: "A spooky improv show at The Comedy Project inspired by the 1990s TV series Are You Afraid of the Dark?, with the cast spinning made-up campfire stories. Expect scary tales and props played for laughs.", source: "https://www.crowdwork.com/e/midnight-society-creepy-improv-comedy" },
  "Late-Night Comedy Lab": { text: "A 45-minute late show in The Comedy Project's 25-seat micro theater, the Comedy Lab. It features improv and sketch groups plus guest spots from TCP's mainstage cast.", source: "https://www.crowdwork.com/e/late-night-comedy-lab" },
  "Comedy Outlet Mondays – Open-mic Variety Show!": { text: "A weekly open-mic variety night at The Comedy Project where performers try out new improv, sketch, stand-up, music and experimental comedy. Every week's lineup is different, and a free improv jam for all skill levels follows the show.", source: "https://www.crowdwork.com/e/comedy-outlet-mondays-open-mic-variety-show" },
  "FREE - Improv Jam-a-lama-ding-dong (Stay for the sing-song!) (Oct 27, Nov 24, Dec 29, Jan 26)": { text: "A free monthly night at The Comedy Project that starts as a hosted improv jam open to anyone who wants to try improv. It then turns into a karaoke jam hosted by Sean \"The Cap'n\" Francis.", source: "https://www.crowdwork.com/e/free-improv-jam-a-lama-ding-dong-stay-for-the-sing-song" },
  "Resting Witch Face - 2026 Halloween NIGHT Sketch show & party": { text: "The Halloween-night performance of The Comedy Project's annual Halloween sketch comedy show. This one adds extra treats, a costume contest and spooky costume karaoke.", source: "https://www.crowdwork.com/e/resting-witch-face-2026-halloween-night-sketch-show-party" },
  "Bard to Go: Grand Valley Shakespeare Festival (free public performance)": { text: "Bard to Go is the Grand Valley Shakespeare Festival's touring outreach show: a 50-minute tour of Shakespeare's best-known scenes that introduces his language and characters. It tours area schools each fall and gives one free public performance, in GVSU's Louis Armstrong Theatre.", source: "https://www.gvsu.edu/mtd/module/79aaee59-6d1b-48aa-bea3-52de6bfb8896/event/7131ce4b-e019-46a5-b3ee-781d713e7410" },
  "Free Play 55: A/B Duo (flute & percussion)": { text: "A/B Duo is flutist Meerenai Shim and percussionist Christopher G. Jones, who have played recent music for audiences around the U.S. since 2013. Their instruments range from contrabass flute and drum set to djembe and a Nintendo Game Boy. This GVSU Free Play concert is in the Sherman Van Solkema Recital Hall.", source: "https://www.gvsu.edu/mtd/module/79aaee59-6d1b-48aa-bea3-52de6bfb8896/event/b0946f97-7121-436a-83b1-0d12baba2c2f" },
  "Love Under The Mistletoe (AVCJ Music holiday concert)": { text: "An intimate holiday concert from AVCJ Music at Midtown at Studio Park, mixing live music with a romantic Christmas atmosphere. The venue pitches it as a date night or an evening out with friends during the holidays.", source: "https://www.themidtowngr.com/shows-events/detail/Love-Under-The-Mistletoe" },
  "Jamie Dionne & Guests: Arts Marketplace Benefit (holiday concert)": { text: "Singer Jamie Dionne's fourth annual holiday concert at Midtown, mixing her original songs with classic and contemporary holiday favorites. Her guest band includes Jeff Leitch of Roosevelt Diggs on drums, and every ticket supports the nonprofit Arts Marketplace at Studio Park.", source: "https://www.themidtowngr.com/shows-events/detail/Jamie-Dionne-Guests-Arts-Marketplace-Benefit" },
  "King Sickabilly With Kitten and The Tonics And Delilah DeWylde": { text: "King Sickabilly is the stage name of Dave \"Sasquatch,\" a Providence, Rhode Island roots musician who has toured nationally for more than 20 years with his band Sasquatch and the Sick-A-Billys. His sound mixes rockabilly and rock 'n' roll with dark country blues; this Grand Rapids date is part of his fall 2026 tour.", source: "https://sickabilly.com/home" },
  "Danger Dear with 50 Waves Of Grey": { text: "Danger Dear is a Kalamazoo-area band playing dark, spooky \"death folk.\" It brings together singer-songwriters Aaron James Wright and Darcy Wilkin with multi-instrumentalists Jay Gavan and Mike Fuerst, who also play in The Corn Fed Girls.", source: "https://www.dormousetheatre.com/events/danger-dear-wsg-helen-yee" },
  "Emma Bieniewicz + Joe Dreams + Statice": { text: "Emma Bieniewicz is a Grand Rapids singer-songwriter and Grand Valley State alumna who makes indie-folk and indie-pop. Her debut album \"bloated\" came out in 2021, followed by a string of singles; she also performs as a classical violinist and violist.", source: "https://emmabieniewicz.bandcamp.com/" },
  "Wynonna Judd – The Hard Truth Tour": { text: "Wynonna Judd is an American country singer who first became famous in the 1980s as half of The Judds, the mother-daughter duo she formed with her mother, Naomi. Across The Judds and her solo career she has scored 19 No. 1 singles, making her one of the most awarded women in country music.", source: W + "Wynonna_Judd" },
  "SPAG – This Is SPAG Tour": { text: "SPAG is the new project of producer Mischa Reining, who spent more than a decade touring as the bass-music DJ Spag Heddy and opened for acts like Zomboy, Excision and Zeds Dead. The venue describes SPAG as a darker, heavier and more stripped-back direction for his sound.", source: "https://sectionlive.com/event/spag-this-is-spag-tour/the-stache/grand-rapids-michigan/" },
  "Avant Theatre Ballet: Visions of Degas (An Original Ballet)": { text: "Avant Theatre Ballet's Visions of Degas is an original ballet on the company's current season, inspired by selections of Edgar Degas's ballet paintings. It follows new characters through the scenes the painter captured. The April 2027 performances are at Fountain Street Church.", source: "https://www.avanttheatreballet.com/current-season" },
};
